#[cfg(test)]
mod dsf_cli_tests {
    use super::*;

    // ---- parse_observed_drop ----

    #[test]
    fn parse_observed_drop_accepts_all_three_suffixes() {
        let (v, u) = parse_observed_drop("5.1mil").unwrap();
        assert!((v - 5.1).abs() < 1e-12);
        assert_eq!(u, DropUnit::Mil);

        let (v, u) = parse_observed_drop("17.4moa").unwrap();
        assert!((v - 17.4).abs() < 1e-12);
        assert_eq!(u, DropUnit::Moa);

        let (v, u) = parse_observed_drop("42.0in").unwrap();
        assert!((v - 42.0).abs() < 1e-12);
        assert_eq!(u, DropUnit::In);
    }

    #[test]
    fn parse_observed_drop_is_case_insensitive_and_trims_whitespace() {
        let (v, u) = parse_observed_drop("  5.1MIL  ").unwrap();
        assert!((v - 5.1).abs() < 1e-12);
        assert_eq!(u, DropUnit::Mil);
    }

    #[test]
    fn parse_observed_drop_rejects_missing_suffix() {
        let e = parse_observed_drop("5.1").unwrap_err();
        assert!(e.contains("mil") && e.contains("moa") && e.contains("in"), "{e}");
    }

    #[test]
    fn parse_observed_drop_rejects_garbage_number() {
        for bad in ["mil", "abcmil", "", "5.1.2moa"] {
            assert!(parse_observed_drop(bad).is_err(), "{bad:?} must be rejected");
        }
    }

    #[test]
    fn parse_observed_drop_rejects_non_finite() {
        assert!(parse_observed_drop("nanmil").is_err());
        assert!(parse_observed_drop("infmoa").is_err());
    }

    // ---- gate/warning helper texts (unit-testable pure functions) ----

    #[test]
    fn supersonic_error_text_is_exact() {
        let msg = dsf_supersonic_error(1.35);
        assert_eq!(
            msg,
            "error: observation is supersonic (Mach 1.35); calibrate muzzle velocity first \
             (true-velocity), then collect DSF points at Mach <= 1.2"
        );
    }

    #[test]
    fn beyond_90pct_warning_text_is_exact() {
        let msg = dsf_beyond_90pct_warning(950.0, "yd");
        assert_eq!(
            msg,
            "warning: observation at 950 yd is beyond 90% of the solved range; solution \
             reliability degrades past this point"
        );
    }

    #[test]
    fn beyond_90pct_warning_text_uses_metric_unit_label() {
        let msg = dsf_beyond_90pct_warning(500.0, "m");
        assert_eq!(
            msg,
            "warning: observation at 500 m is beyond 90% of the solved range; solution \
             reliability degrades past this point"
        );
    }

    #[test]
    fn transonic_gap_warning_text_is_exact() {
        assert_eq!(
            dsf_transonic_gap_warning(),
            "warning: no DSF point in the transonic band (Mach 1.2-0.9); transonic drops \
             remain uncorrected"
        );
    }

    // ---- gate boolean logic ----

    #[test]
    fn observation_beyond_90pct_boundary() {
        assert!(!dsf_observation_beyond_90pct(899.9, 1000.0));
        assert!(!dsf_observation_beyond_90pct(900.0, 1000.0)); // exactly 90%: not beyond
        assert!(dsf_observation_beyond_90pct(900.1, 1000.0));
        assert!(dsf_observation_beyond_90pct(1000.0, 1000.0));
        assert!(!dsf_observation_beyond_90pct(500.0, 0.0)); // degenerate solved range
    }

    // ---- mach_1_crossing_range_m / dsf_observation_warrants_90pct_warning (Critical #1) ----

    fn traj_point(x: f64, velocity_magnitude: f64) -> ballistics_engine::cli_api::TrajectoryPoint {
        ballistics_engine::cli_api::TrajectoryPoint {
            time: 0.0,
            position: nalgebra::Vector3::new(x, 0.0, 0.0),
            velocity_magnitude,
            kinetic_energy: 0.0,
            drag_coefficient: None,
        }
    }

    fn traj_result_fixture(
        points: Vec<ballistics_engine::cli_api::TrajectoryPoint>,
        station_speed_of_sound_mps: f64,
        max_range: f64,
    ) -> ballistics_engine::cli_api::TrajectoryResult {
        ballistics_engine::cli_api::TrajectoryResult {
            max_range,
            max_height: 0.0,
            time_of_flight: 0.0,
            impact_velocity: 0.0,
            impact_energy: 0.0,
            projectile_mass_kg: 0.01,
            line_of_sight_height_m: 0.05,
            station_speed_of_sound_mps,
            termination: ballistics_engine::trajectory_observation::TrajectoryTermination::MaxRange,
            points,
            sampled_points: None,
            min_pitch_damping: None,
            transonic_mach: None,
            angular_state: None,
            max_yaw_angle: None,
            max_precession_angle: None,
            aerodynamic_jump: None,
            mach_1_2_distance_m: None,
            mach_1_0_distance_m: None,
            mach_0_9_distance_m: None,
        }
    }

    #[test]
    fn mach_1_crossing_range_m_interpolates_the_downward_crossing() {
        let sos = 340.0;
        // Mach: 1.3, 1.1, 0.8 at x = 0, 100, 200 -> crosses 1.0 between x=100 (mach 1.1)
        // and x=200 (mach 0.8): t = (1.1 - 1.0) / (1.1 - 0.8) = 1/3 -> x = 100 + 100/3.
        let result = traj_result_fixture(
            vec![
                traj_point(0.0, 1.3 * sos),
                traj_point(100.0, 1.1 * sos),
                traj_point(200.0, 0.8 * sos),
            ],
            sos,
            500.0,
        );
        let crossing = mach_1_crossing_range_m(&result).expect("must find a crossing");
        assert!((crossing - (100.0 + 100.0 / 3.0)).abs() < 1e-6, "{crossing}");
    }

    #[test]
    fn mach_1_crossing_range_m_none_when_trajectory_never_goes_subsonic() {
        let sos = 340.0;
        // Still transonic (Mach 1.05) at the last solved point -> no subsonic crossing yet.
        let result = traj_result_fixture(
            vec![traj_point(0.0, 1.3 * 340.0), traj_point(100.0, 1.05 * sos)],
            sos,
            500.0,
        );
        assert!(mach_1_crossing_range_m(&result).is_none());
    }

    #[test]
    fn mach_1_crossing_range_m_none_for_degenerate_station_speed_of_sound() {
        let result = traj_result_fixture(vec![traj_point(0.0, 300.0)], 0.0, 500.0);
        assert!(mach_1_crossing_range_m(&result).is_none());
    }

    #[test]
    fn warrants_90pct_warning_requires_both_gates() {
        // Beyond 90% of range but still upstream of (or with no) Mach-1.0 crossing: no warning.
        assert!(!dsf_observation_warrants_90pct_warning(950.0, None, 1000.0));
        assert!(!dsf_observation_warrants_90pct_warning(950.0, Some(960.0), 1000.0));

        // Beyond the crossing but NOT beyond 90% of range: no warning.
        assert!(!dsf_observation_warrants_90pct_warning(500.0, Some(400.0), 1000.0));

        // Beyond both: warns.
        assert!(dsf_observation_warrants_90pct_warning(950.0, Some(400.0), 1000.0));
    }

    #[test]
    fn transonic_coverage_gate_checks_highest_point_only() {
        assert!(dsf_table_missing_transonic_coverage(&[]));
        assert!(dsf_table_missing_transonic_coverage(&[DsfPoint {
            mach: 0.5,
            dsf: 1.1
        }]));
        assert!(!dsf_table_missing_transonic_coverage(&[
            DsfPoint { mach: 0.5, dsf: 1.1 },
            DsfPoint { mach: 0.95, dsf: 1.05 },
        ]));
        // Exactly at the 0.9 boundary counts as covered (< 0.9 is the gate, not <=).
        assert!(!dsf_table_missing_transonic_coverage(&[DsfPoint {
            mach: 0.9,
            dsf: 1.0
        }]));
    }

    // ---- dsf_table_summary ----

    #[test]
    fn table_summary_formats_count_and_mach_span() {
        let points = vec![
            DsfPoint { mach: 0.6, dsf: 1.1 },
            DsfPoint { mach: 0.85, dsf: 1.02 },
        ];
        assert_eq!(dsf_table_summary(&points), "2 points, Mach 0.60-0.85");
    }

    // ---- interpolate_position_and_velocity ----

    fn pt(x: f64, y: f64, v: f64) -> ballistics_engine::cli_api::TrajectoryPoint {
        ballistics_engine::cli_api::TrajectoryPoint {
            time: 0.0,
            position: nalgebra::Vector3::new(x, y, 0.0),
            velocity_magnitude: v,
            kinetic_energy: 0.0,
            drag_coefficient: None,
        }
    }

    #[test]
    fn interpolates_linearly_between_bracketing_points() {
        let points = vec![pt(0.0, 1.0, 800.0), pt(100.0, 0.5, 700.0)];
        let (y, v) = interpolate_position_and_velocity(&points, 50.0).unwrap();
        assert!((y - 0.75).abs() < 1e-9);
        assert!((v - 750.0).abs() < 1e-9);
    }

    #[test]
    fn interpolation_returns_none_past_the_last_point() {
        let points = vec![pt(0.0, 1.0, 800.0), pt(100.0, 0.5, 700.0)];
        assert!(interpolate_position_and_velocity(&points, 200.0).is_none());
    }

    #[test]
    fn interpolation_at_or_before_the_first_point_returns_its_own_values() {
        let points = vec![pt(0.0, 1.0, 800.0), pt(100.0, 0.5, 700.0)];
        let (y, v) = interpolate_position_and_velocity(&points, 0.0).unwrap();
        assert_eq!(y, 1.0);
        assert_eq!(v, 800.0);
    }
}

/// Print one built-in reference drag curve as `(Mach, Cd)` data (MBA-1424).
///
/// The engine already carries these tables; this hands them back so a consumer charting drag
/// does not have to re-vendor the numbers and then drift from the engine as tables are refined.
/// Emitted verbatim from the table — no resampling, no interpolation onto a uniform grid — so
/// what you plot is exactly what the solver interpolates.
/// `hold-corridor` (MBA-1349).
#[allow(
    clippy::too_many_arguments,
    reason = "flat arguments mirror the stable Clap command shape"
)]
fn handle_hold_corridor(
    scenarios_path: PathBuf,
    ranges: String,
    target: Option<String>,
    profile: Option<String>,
    velocity: Option<f64>,
    bc: Option<f64>,
    mass: Option<f64>,
    diameter: Option<f64>,
    drag_model: DragModel,
    zero_distance: Option<f64>,
    sight_height: Option<f64>,
    temperature: Option<f64>,
    pressure: Option<f64>,
    pressure_type: Option<PressureReferenceMode>,
    humidity: f64,
    altitude: f64,
    units: UnitSystem,
    output: OutputFormat,
) -> Result<(), Box<dyn Error>> {
    let format = match output {
        OutputFormat::Table => RobustHoldFormat::Table,
        OutputFormat::Json => RobustHoldFormat::Json,
        OutputFormat::Csv => {
            return Err(
                "hold-corridor has no CSV form (a corridor row is a block, not a line); \
                 use -o table or -o json"
                    .into(),
            )
        }
        OutputFormat::Pdf => {
            return Err("hold-corridor has no PDF form; use -o table or -o json".into())
        }
    };

    // File I/O lives here; `wind_scenarios` parses TEXT so it stays wasm32-clean.
    let text = fs::read_to_string(&scenarios_path).map_err(|e| {
        format!(
            "could not read scenario file {}: {e}",
            scenarios_path.display()
        )
    })?;
    // `main` prints errors with Debug, so typed errors are rendered here through
    // Display and handed on as strings — the same shape every other subcommand's
    // messages take.
    let scenario_set = parse_wind_scenario_set(&text, units).map_err(|e| e.to_string())?;

    let ranges_m: Vec<f64> = ranges
        .split(',')
        .map(|token| {
            let value: f64 = token.trim().parse().map_err(|_| {
                format!("invalid --ranges entry '{}': expected a number", token.trim())
            })?;
            Ok::<f64, String>(UnitConverter::distance_to_metric(value, units))
        })
        .collect::<Result<_, _>>()?;

    let target = match target.as_deref() {
        Some(spec) => Some(parse_target_spec(spec, units).map_err(|e| e.to_string())?),
        None => None,
    };

    let profile_data = match profile.as_deref() {
        Some(name) => Some(load_profile(name)?),
        None => None,
    };
    let require = |value: Option<f64>, flag: &str| -> Result<f64, Box<dyn Error>> {
        value.ok_or_else(|| format!("{flag} is required (directly or from --profile)").into())
    };
    let velocity = require(
        resolve_param(velocity, &profile_data, |p| p.velocity),
        "--velocity",
    )?;
    let bc = require(resolve_param(bc, &profile_data, |p| p.bc), "--bc")?;
    let mass = require(resolve_param(mass, &profile_data, |p| p.mass), "--mass")?;
    let diameter = require(
        resolve_param(diameter, &profile_data, |p| p.diameter),
        "--diameter",
    )?;
    let zero_distance = require(
        zero_distance.or_else(|| profile_data.as_ref().and_then(|p| p.zero_distance)),
        "--zero-distance",
    )?;
    // Same fallback `trajectory --saved-profile`/`come-ups --profile` use.
    let sight_height = sight_height
        .or_else(|| profile_data.as_ref().and_then(|p| p.sight_height))
        .unwrap_or(match units {
            UnitSystem::Imperial => 2.0,
            UnitSystem::Metric => 50.0,
        });
    let temperature = UnitConverter::resolve_temperature(temperature, units)?;
    // MBA-1416: a declared QNH reduces against this command's own --altitude.
    let pressure = apply_pressure_mode(
        UnitConverter::resolve_pressure(pressure, units)?,
        altitude,
        pressure_type,
        units,
    );

    let mass_kg = UnitConverter::mass_to_metric(mass, units);
    let diameter_m = UnitConverter::diameter_to_metric(diameter, units);
    let request = RobustHoldRequest {
        scenarios: scenario_set,
        ranges_m,
        target,
        load: CorridorLoad {
            muzzle_velocity_mps: UnitConverter::velocity_to_metric(velocity, units),
            bc,
            drag_model,
            mass_kg,
            diameter_m,
            bullet_length_m: fallback_bullet_length_m(diameter_m, mass_kg),
            zero_distance_m: UnitConverter::distance_to_metric(zero_distance, units),
            sight_height_m: UnitConverter::sight_height_to_metric(sight_height, units),
            temperature_c: UnitConverter::temperature_to_metric(temperature, units),
            pressure_hpa: UnitConverter::pressure_to_metric(pressure, units),
            humidity_pct: humidity,
            altitude_m: UnitConverter::altitude_to_metric(altitude, units),
        },
    };

    let report = solve_robust_hold(&request).map_err(|e| e.to_string())?;
    print!("{}", format_robust_hold_report(&report, format, units));
    Ok(())
}

/// Golden ratio conjugate, the fixed step constant of the `optimal-zero` search
/// (MBA-1362). Hard-coded rather than derived at run time so the search is bit-for-bit
/// reproducible across builds.
const GOLDEN_SECTION_RATIO: f64 = 0.618_033_988_749_894_9;

/// Iteration cap for the `optimal-zero` golden-section search. Each step shrinks the
/// bracket by [`GOLDEN_SECTION_RATIO`], so a 2000 m bracket reaches the tolerance below in
/// about 25; the rest is runaway guard.
const OPTIMAL_ZERO_MAX_ITERATIONS: u32 = 60;

/// Bracket width (meters) at which the `optimal-zero` search stops. A centimeter of zero
/// distance is far below what anyone can set a zero to.
const OPTIMAL_ZERO_TOLERANCE_M: f64 = 0.01;

/// Smallest and largest zero distance the `optimal-zero` bracket will consider, meters.
const OPTIMAL_ZERO_MIN_M: f64 = 10.0;
const OPTIMAL_ZERO_MAX_M: f64 = 2000.0;

/// Convert one NOMINAL mark subtension to TRUE angular milliradians (MBA-1362).
///
/// The single conversion all three inverse solvers use, so none of them can disagree about
/// what a second-focal-plane mark covers. FFP is an exact identity.
fn true_subtension_mil(nominal_mil: f64, focal_plane: FocalPlane, scale: f64) -> f64 {
    match focal_plane {
        FocalPlane::First => nominal_mil,
        FocalPlane::Second => nominal_mil * scale,
    }
}

/// `mark-to-range` (MBA-1362).
#[allow(
    clippy::too_many_arguments,
    reason = "flat arguments mirror the stable Clap command shape"
)]
fn handle_mark_to_range(
    marks: Vec<f64>,
    reticle_json: Option<PathBuf>,
    mag: f64,
    focal_plane: FocalPlaneArg,
    reference_mag: f64,
    zero_distance: Option<f64>,
    max_range: f64,
    load_args: InverseSolverLoadArgs,
    units: UnitSystem,
    output: OutputFormat,
) -> Result<(), Box<dyn Error>> {
    let format = reticle_format(output)?;

    // Subtension source. A reticle file carries its OWN focal plane and reference
    // magnification, which win over the flags — a description that says "SFP at 12x" is
    // authoritative about itself.
    let (nominal_marks, plane, reference_mag, excluded, source_name) = match &reticle_json {
        Some(path) => {
            if !marks.is_empty() {
                return Err("--mark and --reticle-json are mutually exclusive".into());
            }
            let description = load_reticle_description(path)?;
            // Marks on the vertical stadium, INCLUDING any above center: those come back
            // as "not a holdover" rows rather than being quietly dropped. Only genuinely
            // off-axis marks (windage dots) and the optical center itself are excluded,
            // and the count of those is reported.
            let holdovers: Vec<f64> = description
                .marks
                .iter()
                .filter(|m| m.right_mil == 0.0 && m.down_mil != 0.0)
                .map(|m| m.down_mil)
                .collect();
            let excluded = description.marks.len() - holdovers.len();
            if holdovers.is_empty() {
                return Err(format!(
                    "reticle '{}' has no marks on the vertical stadium to map to a range \
                     (only the optical center and off-axis windage marks)",
                    description.name
                )
                .into());
            }
            (
                holdovers,
                description.focal_plane,
                description.reference_magnification,
                excluded,
                description.name,
            )
        }
        None => {
            if marks.is_empty() {
                return Err(
                    "at least one --mark <MIL> is required (or --reticle-json <FILE>)".into(),
                );
            }
            for mark in &marks {
                if !mark.is_finite() {
                    return Err(format!("--mark {mark} must be a finite subtension").into());
                }
            }
            (
                marks,
                focal_plane.into(),
                reference_mag,
                0,
                "supplied marks".to_string(),
            )
        }
    };
    if plane == FocalPlane::Second && (!reference_mag.is_finite() || reference_mag <= 0.0) {
        return Err("an SFP reticle needs a positive reference magnification".into());
    }
    let scale = reference_mag / mag;

    let (load, _) = load_args.resolve(zero_distance, units)?;
    let max_range_m = UnitConverter::distance_to_metric(max_range, units);
    // Search a little past the requested limit so a mark landing exactly at it still
    // brackets.
    let curve = HoldCurve::solve(&load, max_range_m * 1.02)?;

    struct Row {
        nominal_mil: f64,
        true_mil: f64,
        outcome: MarkToRangeOutcome,
    }
    let rows: Vec<Row> = nominal_marks
        .iter()
        .map(|&nominal_mil| {
            let true_mil = true_subtension_mil(nominal_mil, plane, scale);
            Row {
                nominal_mil,
                true_mil,
                outcome: curve.range_for_angular_drop_mil(true_mil),
            }
        })
        .collect();

    let (dist_unit, vel_unit, energy_unit) = match units {
        UnitSystem::Imperial => ("yd", "fps", "ft-lb"),
        UnitSystem::Metric => ("m", "m/s", "J"),
    };

    match format {
        ReticleFormat::Json => {
            let entries: Vec<serde_json::Value> = rows
                .iter()
                .map(|row| match &row.outcome {
                    MarkToRangeOutcome::Reached(point) => serde_json::json!({
                        "nominal_mil": row.nominal_mil,
                        "true_mil": row.true_mil,
                        "status": "reached",
                        "range": UnitConverter::distance_from_metric(point.range_m, units),
                        "time": point.time_s,
                        "velocity": UnitConverter::velocity_from_metric(point.velocity_mps, units),
                        "energy": UnitConverter::energy_from_metric(point.energy_j, units),
                    }),
                    MarkToRangeOutcome::InsideZero { far_zero_range_m } => serde_json::json!({
                        "nominal_mil": row.nominal_mil,
                        "true_mil": row.true_mil,
                        "status": "not_a_holdover",
                        "far_zero_range": UnitConverter::distance_from_metric(*far_zero_range_m, units),
                    }),
                    MarkToRangeOutcome::BeyondSearch { max_range_m, max_drop_mil } => {
                        serde_json::json!({
                            "nominal_mil": row.nominal_mil,
                            "true_mil": row.true_mil,
                            "status": "beyond_max_range",
                            "max_range": UnitConverter::distance_from_metric(*max_range_m, units),
                            "max_drop_mil": max_drop_mil,
                        })
                    }
                })
                .collect();
            let value = serde_json::json!({
                "reticle": source_name,
                "focal_plane": plane.label(),
                "reference_magnification": reference_mag,
                "magnification": mag,
                "mark_scale": if plane == FocalPlane::Second { scale } else { 1.0 },
                "zero_distance": UnitConverter::distance_from_metric(load.zero_distance_m, units),
                "distance_unit": dist_unit,
                "velocity_unit": vel_unit,
                "energy_unit": energy_unit,
                "excluded_marks": excluded,
                "marks": entries,
            });
            println!("{}", serde_json::to_string_pretty(&value)?);
        }
        ReticleFormat::Table => {
            println!("Mark-to-Range");
            println!("=============\n");
            println!("Reticle:      {source_name}");
            println!("Focal plane:  {}", plane.label());
            if plane == FocalPlane::Second {
                println!("Reference:    {reference_mag:.2}x   In use: {mag:.2}x   Subtension scale: {scale:.4}x");
            }
            println!(
                "Zero:         {:.0} {}\n",
                UnitConverter::distance_from_metric(load.zero_distance_m, units),
                dist_unit
            );
            if excluded > 0 {
                println!(
                    "Note: {excluded} mark(s) excluded — the optical center and off-axis \
                     windage marks do not map to a range.\n"
                );
            }
            println!(
                "Mark(mil)  True(mil)  Range({dist_unit})  Time(s)  Vel({vel_unit})  Energy({energy_unit})"
            );
            println!("---------  ---------  ----------  -------  ----------  ------------");
            for row in &rows {
                match &row.outcome {
                    MarkToRangeOutcome::Reached(point) => println!(
                        "{:>9.2}  {:>9.3}  {:>10.0}  {:>7.3}  {:>10.0}  {:>12.0}",
                        row.nominal_mil,
                        row.true_mil,
                        UnitConverter::distance_from_metric(point.range_m, units),
                        point.time_s,
                        UnitConverter::velocity_from_metric(point.velocity_mps, units),
                        UnitConverter::energy_from_metric(point.energy_j, units)
                    ),
                    MarkToRangeOutcome::InsideZero { far_zero_range_m } => println!(
                        "{:>9.2}  {:>9.3}  {:>10}  (not a holdover: drop is 0 at the far zero, {:.0} {}, and only grows past it)",
                        row.nominal_mil,
                        row.true_mil,
                        "-",
                        UnitConverter::distance_from_metric(*far_zero_range_m, units),
                        dist_unit
                    ),
                    MarkToRangeOutcome::BeyondSearch {
                        max_range_m,
                        max_drop_mil,
                    } => println!(
                        "{:>9.2}  {:>9.3}  {:>10}  (never reached: {:.2} mil at {:.0} {} is the most this load drops)",
                        row.nominal_mil,
                        row.true_mil,
                        "-",
                        max_drop_mil,
                        UnitConverter::distance_from_metric(*max_range_m, units),
                        dist_unit
                    ),
                }
            }
        }
    }
    Ok(())
}

/// One `bdc-match --mark-range MIL:RANGE` pair, parsed (MBA-1362).
struct BdcMatchPair {
    nominal_mil: f64,
    range_display: f64,
    range_m: f64,
}

fn parse_bdc_match_pair(token: &str, units: UnitSystem) -> Result<BdcMatchPair, String> {
    let parts: Vec<&str> = token.split(':').collect();
    if parts.len() != 2 {
        return Err(format!(
            "invalid --mark-range '{token}': expected MIL:RANGE (e.g. 2.0:300)"
        ));
    }
    let nominal_mil: f64 = parts[0]
        .trim()
        .parse()
        .map_err(|_| format!("invalid --mark-range subtension '{}' in '{token}'", parts[0]))?;
    let range: f64 = parts[1]
        .trim()
        .parse()
        .map_err(|_| format!("invalid --mark-range range '{}' in '{token}'", parts[1]))?;
    if !nominal_mil.is_finite() || nominal_mil <= 0.0 {
        return Err(format!(
            "invalid --mark-range '{token}': the subtension must be a positive holdover in \
             milliradians"
        ));
    }
    if !range.is_finite() || range <= 0.0 {
        return Err(format!(
            "invalid --mark-range '{token}': the range must be finite and greater than zero"
        ));
    }
    Ok(BdcMatchPair {
        nominal_mil,
        range_display: range,
        range_m: UnitConverter::distance_to_metric(range, units),
    })
}

/// `bdc-match` (MBA-1362).
#[allow(
    clippy::too_many_arguments,
    reason = "flat arguments mirror the stable Clap command shape"
)]
fn handle_bdc_match(
    mark_ranges: Vec<String>,
    reference_mag: f64,
    focal_plane: FocalPlaneArg,
    residual_warn: f64,
    zero_distance: Option<f64>,
    load_args: InverseSolverLoadArgs,
    units: UnitSystem,
    output: OutputFormat,
) -> Result<(), Box<dyn Error>> {
    let format = reticle_format(output)?;
    if FocalPlane::from(focal_plane) == FocalPlane::First {
        return Err(
            "bdc-match applies to SECOND focal plane reticles only: an FFP reticle's \
             subtensions are the same at every magnification, so no magnification makes it \
             match a load better than any other. Use `mark-to-range` to see where its marks \
             land instead."
                .into(),
        );
    }
    let pairs: Vec<BdcMatchPair> = mark_ranges
        .iter()
        .map(|token| parse_bdc_match_pair(token, units))
        .collect::<Result<_, _>>()?;
    if pairs.len() < 2 {
        return Err(
            "bdc-match needs at least two --mark-range MIL:RANGE pairs to fit a magnification \
             (one pair is satisfied exactly by some magnification and says nothing about fit)"
                .into(),
        );
    }

    let (load, _) = load_args.resolve(zero_distance, units)?;
    let furthest_m = pairs.iter().fold(0.0_f64, |acc, p| acc.max(p.range_m));
    let curve = HoldCurve::solve(&load, furthest_m * 1.05)?;

    // Solved angular drop at each mark's nominal range.
    let mut solved_mil = Vec::with_capacity(pairs.len());
    for pair in &pairs {
        let point = curve.at_range(pair.range_m).ok_or_else(|| {
            format!(
                "the trajectory does not reach {:.0} — it was solved only to {:.0}",
                pair.range_display,
                UnitConverter::distance_from_metric(curve.max_sampled_range_m(), units)
            )
        })?;
        solved_mil.push(point.drop_mil);
    }

    // The fit. The apparent subtension of mark i at magnification M is
    //     a_i(M) = s_i * reference_mag / M
    // so substituting u = reference_mag / M makes the residual LINEAR in u:
    //     minimize  sum_i (s_i * u - t_i)^2
    // whose minimizer is the ordinary least-squares slope through the origin,
    //     u* = sum(s_i t_i) / sum(s_i^2),
    // and the fitted magnification is reference_mag / u*. Closed form, so it is exact,
    // deterministic, and cannot depend on a starting guess or an iteration count.
    let sum_st: f64 = pairs
        .iter()
        .zip(&solved_mil)
        .map(|(pair, t)| pair.nominal_mil * t)
        .sum();
    let sum_ss: f64 = pairs.iter().map(|pair| pair.nominal_mil.powi(2)).sum();
    if sum_ss <= 0.0 {
        return Err("the supplied subtensions carry no information to fit".into());
    }
    let u = sum_st / sum_ss;
    if !u.is_finite() || u <= 0.0 {
        return Err(
            "no positive magnification fits these marks: the solved drops and the supplied \
             subtensions disagree in sign (check that the ranges pair with the right marks)"
                .into(),
        );
    }
    let fitted_mag = reference_mag / u;

    struct Residual {
        nominal_mil: f64,
        range_display: f64,
        apparent_mil: f64,
        solved_mil: f64,
        residual_mil: f64,
    }
    let residuals: Vec<Residual> = pairs
        .iter()
        .zip(&solved_mil)
        .map(|(pair, &t)| {
            let apparent = pair.nominal_mil * u;
            Residual {
                nominal_mil: pair.nominal_mil,
                range_display: pair.range_display,
                apparent_mil: apparent,
                solved_mil: t,
                residual_mil: apparent - t,
            }
        })
        .collect();
    let worst = residuals
        .iter()
        .fold(0.0_f64, |acc, r| acc.max(r.residual_mil.abs()));
    let rms = (residuals
        .iter()
        .map(|r| r.residual_mil.powi(2))
        .sum::<f64>()
        / residuals.len() as f64)
        .sqrt();

    let dist_unit = match units {
        UnitSystem::Imperial => "yd",
        UnitSystem::Metric => "m",
    };

    match format {
        ReticleFormat::Json => {
            let value = serde_json::json!({
                "fitted_magnification": fitted_mag,
                "reference_magnification": reference_mag,
                "subtension_scale": u,
                "zero_distance": UnitConverter::distance_from_metric(load.zero_distance_m, units),
                "distance_unit": dist_unit,
                "worst_residual_mil": worst,
                "rms_residual_mil": rms,
                "residual_warn_mil": residual_warn,
                "fit_warning": worst > residual_warn,
                "marks": residuals.iter().map(|r| serde_json::json!({
                    "nominal_mil": r.nominal_mil,
                    "range": r.range_display,
                    "apparent_mil": r.apparent_mil,
                    "solved_drop_mil": r.solved_mil,
                    "residual_mil": r.residual_mil,
                })).collect::<Vec<_>>(),
            });
            println!("{}", serde_json::to_string_pretty(&value)?);
        }
        ReticleFormat::Table => {
            println!("BDC Magnification Match");
            println!("=======================\n");
            println!("Reference magnification: {reference_mag:.2}x");
            println!("Fitted magnification:    {fitted_mag:.3}x");
            println!("Subtension scale at fit: {u:.4}x");
            println!(
                "Zero:                    {:.0} {}\n",
                UnitConverter::distance_from_metric(load.zero_distance_m, units),
                dist_unit
            );
            println!(
                "Mark(mil)  Range({dist_unit})  Apparent(mil)  Drop(mil)  Residual(mil)"
            );
            println!("---------  ----------  -------------  ---------  -------------");
            for r in &residuals {
                println!(
                    "{:>9.2}  {:>10.0}  {:>13.3}  {:>9.3}  {:>13.3}",
                    r.nominal_mil, r.range_display, r.apparent_mil, r.solved_mil, r.residual_mil
                );
            }
            println!("\nWorst residual: {worst:.3} mil   RMS: {rms:.3} mil");
            if worst > residual_warn {
                println!(
                    "\nWARNING: the worst residual exceeds {residual_warn:.3} mil — this reticle \
                     does not fit this load well at ANY magnification. Treat the fitted value as \
                     the least-bad compromise, not a BDC calibration."
                );
            }
        }
    }
    Ok(())
}

/// One `optimal-zero --target RANGE[:HEIGHT]` entry, parsed (MBA-1362).
struct OptimalZeroTarget {
    range_display: f64,
    range_m: f64,
    /// Full vertical size, meters. `None` until `--vital` fills it in.
    height_m: Option<f64>,
}

fn parse_optimal_zero_target(
    token: &str,
    units: UnitSystem,
) -> Result<OptimalZeroTarget, String> {
    let parts: Vec<&str> = token.split(':').collect();
    if parts.len() != 1 && parts.len() != 2 {
        return Err(format!(
            "invalid --target '{token}': expected RANGE or RANGE:HEIGHT (e.g. 400 or 400:12)"
        ));
    }
    let range: f64 = parts[0]
        .trim()
        .parse()
        .map_err(|_| format!("invalid --target range '{}' in '{token}'", parts[0]))?;
    if !range.is_finite() || range <= 0.0 {
        return Err(format!(
            "invalid --target '{token}': the range must be finite and greater than zero"
        ));
    }
    let height = match parts.get(1) {
        Some(token_height) => {
            let value: f64 = token_height
                .trim()
                .parse()
                .map_err(|_| format!("invalid --target height '{token_height}' in '{token}'"))?;
            if !value.is_finite() || value <= 0.0 {
                return Err(format!(
                    "invalid --target '{token}': the height must be finite and greater than zero"
                ));
            }
            Some(value)
        }
        None => None,
    };
    Ok(OptimalZeroTarget {
        range_display: range,
        range_m: UnitConverter::distance_to_metric(range, units),
        // Inches imperial / centimeters metric, matching `mpbr --vital-zone`.
        height_m: height.map(|value| match units {
            UnitSystem::Imperial => value * 0.0254,
            UnitSystem::Metric => value * 0.01,
        }),
    })
}

/// `optimal-zero` (MBA-1362).
fn handle_optimal_zero(
    targets: Vec<String>,
    vital: Option<f64>,
    load_args: InverseSolverLoadArgs,
    units: UnitSystem,
    output: OutputFormat,
) -> Result<(), Box<dyn Error>> {
    const MIN_TARGETS: usize = 2;
    const MAX_TARGETS: usize = 16;

    let format = reticle_format(output)?;
    let mut parsed: Vec<OptimalZeroTarget> = targets
        .iter()
        .map(|token| parse_optimal_zero_target(token, units))
        .collect::<Result<_, _>>()?;
    if parsed.len() < MIN_TARGETS || parsed.len() > MAX_TARGETS {
        return Err(format!(
            "optimal-zero needs {MIN_TARGETS} to {MAX_TARGETS} --target entries (got {}): one \
             target is just a zero distance, and beyond {MAX_TARGETS} the min-max answer is \
             dominated by the extremes anyway",
            parsed.len()
        )
        .into());
    }
    let vital_m = vital.map(|value| match units {
        UnitSystem::Imperial => value * 0.0254,
        UnitSystem::Metric => value * 0.01,
    });
    for target in parsed.iter_mut() {
        if target.height_m.is_none() {
            target.height_m = vital_m;
        }
        if target.height_m.is_none() {
            return Err(format!(
                "--target {} carries no height and no --vital was given; one of the two must \
                 say how big the target is",
                target.range_display
            )
            .into());
        }
    }
    // Sorted by range so the report reads in order regardless of entry order, and so the
    // reported worst-case target is a deterministic choice among ties.
    parsed.sort_by(|a, b| a.range_m.total_cmp(&b.range_m));

    let furthest_m = parsed.iter().fold(0.0_f64, |acc, t| acc.max(t.range_m));
    let nearest_m = parsed
        .iter()
        .fold(f64::INFINITY, |acc, t| acc.min(t.range_m));
    let curve_max_m = furthest_m * 1.05;

    // Resolve the load ONCE, so a missing flag is an error here rather than a mysterious
    // "no zero could be solved" later, and so the saved profile is read once rather than
    // once per search iteration. The zero distance handed in is a placeholder — this
    // command solves for it, and every candidate below overwrites it.
    let (base_load, _) = load_args.resolve(Some(1.0), units)?;

    // Holds at every target for one candidate zero: one solve, read at each range.
    let holds_at = |zero_m: f64| -> Option<Vec<f64>> {
        let mut load = base_load.clone();
        load.zero_distance_m = zero_m;
        let curve = HoldCurve::solve(&load, curve_max_m).ok()?;
        parsed
            .iter()
            .map(|target| curve.at_range(target.range_m).map(|p| p.drop_mil))
            .collect()
    };

    // The objective: the LARGEST hold any target needs. It is quasiconvex in zero
    // distance — increasing the zero shifts every range's required hold by very nearly the
    // same angular amount, and the max of |linear functions| is convex — so golden-section
    // search is valid and, with fixed constants, deterministic.
    let objective = |zero_m: f64| -> f64 {
        match holds_at(zero_m) {
            Some(holds) => holds.iter().fold(0.0_f64, |acc, h| acc.max(h.abs())),
            // An unsolvable candidate is pushed away from rather than crashing the search.
            None => f64::INFINITY,
        }
    };

    let mut lo = (nearest_m * 0.15).max(OPTIMAL_ZERO_MIN_M);
    let mut hi = (furthest_m * 1.05).min(OPTIMAL_ZERO_MAX_M).max(lo + 1.0);
    let mut x1 = hi - GOLDEN_SECTION_RATIO * (hi - lo);
    let mut x2 = lo + GOLDEN_SECTION_RATIO * (hi - lo);
    let mut f1 = objective(x1);
    let mut f2 = objective(x2);
    for _ in 0..OPTIMAL_ZERO_MAX_ITERATIONS {
        if hi - lo <= OPTIMAL_ZERO_TOLERANCE_M {
            break;
        }
        if f1 < f2 {
            hi = x2;
            x2 = x1;
            f2 = f1;
            x1 = hi - GOLDEN_SECTION_RATIO * (hi - lo);
            f1 = objective(x1);
        } else {
            lo = x1;
            x1 = x2;
            f1 = f2;
            x2 = lo + GOLDEN_SECTION_RATIO * (hi - lo);
            f2 = objective(x2);
        }
    }
    let best_zero_m = 0.5 * (lo + hi);
    let holds = holds_at(best_zero_m).ok_or_else(|| {
        format!(
            "no trajectory could be solved at the fitted zero of {:.1} {}",
            UnitConverter::distance_from_metric(best_zero_m, units),
            match units {
                UnitSystem::Imperial => "yd",
                UnitSystem::Metric => "m",
            }
        )
    })?;

    struct TargetRow {
        range_display: f64,
        height_m: f64,
        hold_mil: f64,
        /// Signed vertical displacement of a DEAD-CENTER hold, meters. Positive = the
        /// bullet lands low.
        offset_m: f64,
        fits: bool,
    }
    let rows: Vec<TargetRow> = parsed
        .iter()
        .zip(&holds)
        .map(|(target, &hold_mil)| {
            let height_m = target.height_m.expect("filled in above");
            let offset_m = hold_mil / 1000.0 * target.range_m;
            TargetRow {
                range_display: target.range_display,
                height_m,
                hold_mil,
                offset_m,
                // Boundary contact counts as a fit.
                fits: offset_m.abs() <= height_m / 2.0,
            }
        })
        .collect();
    let max_hold_mil = rows.iter().fold(0.0_f64, |acc, r| acc.max(r.hold_mil.abs()));
    let all_fit = rows.iter().all(|r| r.fits);

    let (dist_unit, size_unit) = match units {
        UnitSystem::Imperial => ("yd", "in"),
        UnitSystem::Metric => ("m", "cm"),
    };
    let size_from_m = |value: f64| match units {
        UnitSystem::Imperial => value / 0.0254,
        UnitSystem::Metric => value * 100.0,
    };

    match format {
        ReticleFormat::Json => {
            let value = serde_json::json!({
                "optimal_zero": UnitConverter::distance_from_metric(best_zero_m, units),
                "distance_unit": dist_unit,
                "size_unit": size_unit,
                "max_hold_mil": max_hold_mil,
                "all_targets_fit": all_fit,
                "targets": rows.iter().map(|r| serde_json::json!({
                    "range": r.range_display,
                    "height": size_from_m(r.height_m),
                    "hold_mil": r.hold_mil,
                    "offset": size_from_m(r.offset_m),
                    "fits": r.fits,
                })).collect::<Vec<_>>(),
            });
            println!("{}", serde_json::to_string_pretty(&value)?);
        }
        ReticleFormat::Table => {
            println!("Optimal Zero (min-max hold)");
            println!("===========================\n");
            println!(
                "Optimal zero:  {:.1} {}",
                UnitConverter::distance_from_metric(best_zero_m, units),
                dist_unit
            );
            println!("Largest hold:  {max_hold_mil:.3} mil\n");
            println!(
                "Range({dist_unit})  Target({size_unit})  Hold(mil)  Center-hold miss({size_unit})  Fits"
            );
            println!("----------  ----------  ---------  ---------------------  ----");
            for r in &rows {
                println!(
                    "{:>10.0}  {:>10.1}  {:>9.3}  {:>21.2}  {}",
                    r.range_display,
                    size_from_m(r.height_m),
                    r.hold_mil,
                    size_from_m(r.offset_m),
                    if r.fits { "yes" } else { "NO" }
                );
            }
            println!(
                "\n{}",
                if all_fit {
                    "Every target is inside its vital zone with a dead-center hold."
                } else {
                    "At least one target needs a hold: no single zero keeps them all centered."
                }
            );
            println!(
                "Center-hold miss is signed: positive = the bullet lands LOW of the aim point."
            );
        }
    }
    Ok(())
}

/// Map an `OutputFormat` onto the reticle formatter's two shapes (MBA-1361).
///
/// CSV and PDF are rejected here rather than in the library, because each surface owns its
/// own error convention — the same split `run_drag_curve` uses.
fn reticle_format(output: OutputFormat) -> Result<ReticleFormat, Box<dyn Error>> {
    match output {
        OutputFormat::Table => Ok(ReticleFormat::Table),
        OutputFormat::Json => Ok(ReticleFormat::Json),
        OutputFormat::Csv => {
            Err("reticle output has no CSV form; use -o table or -o json".into())
        }
        OutputFormat::Pdf => {
            Err("reticle output has no PDF form; use -o table or -o json".into())
        }
    }
}

/// Parse one `reticle generate bdc --drop RANGE:DROP_MIL` token into
/// `(range_display, range_m, drop_mil)`.
///
/// RANGE follows `--units`; DROP_MIL is always milliradians (an angle, so unit-invariant —
/// the same reasoning that keeps turret graduations out of `converted_to`). The display
/// range comes back too so the caller can label marks in the units the user typed.
fn parse_reticle_bdc_drop(token: &str, units: UnitSystem) -> Result<(f64, f64, f64), String> {
    let parts: Vec<&str> = token.split(':').collect();
    if parts.len() != 2 {
        return Err(format!(
            "invalid --drop '{token}': expected RANGE:DROP_MIL (e.g. 400:2.7)"
        ));
    }
    let range: f64 = parts[0]
        .trim()
        .parse()
        .map_err(|_| format!("invalid --drop range '{}' in '{token}'", parts[0]))?;
    let drop_mil: f64 = parts[1]
        .trim()
        .parse()
        .map_err(|_| format!("invalid --drop value '{}' in '{token}'", parts[1]))?;
    if !range.is_finite() || range <= 0.0 {
        return Err(format!(
            "invalid --drop '{token}': range must be finite and greater than zero"
        ));
    }
    if !drop_mil.is_finite() {
        return Err(format!("invalid --drop '{token}': drop must be finite"));
    }
    Ok((
        range,
        UnitConverter::distance_to_metric(range, units),
        drop_mil,
    ))
}

/// `reticle` dispatch (MBA-1361).
fn handle_reticle(action: ReticleAction, units: UnitSystem) -> Result<(), Box<dyn Error>> {
    match action {
        ReticleAction::Generate { layout } => {
            let (mut description, common) = match layout {
                ReticleLayout::MilGrid {
                    spacing,
                    extent,
                    common,
                } => (
                    ReticleDescription::mil_grid(spacing, extent)
                        .map_err(|e| e.to_string())?,
                    common,
                ),
                ReticleLayout::Tree {
                    rows,
                    row_spacing,
                    spread_step,
                    common,
                } => (
                    ReticleDescription::tree(rows, row_spacing, spread_step)
                        .map_err(|e| e.to_string())?,
                    common,
                ),
                ReticleLayout::Bdc { drops, common } => {
                    let parsed = drops
                        .iter()
                        .map(|token| parse_reticle_bdc_drop(token, units))
                        .collect::<Result<Vec<_>, _>>()?;
                    let metric: Vec<(f64, f64)> = parsed
                        .iter()
                        .map(|&(_, range_m, drop_mil)| (range_m, drop_mil))
                        .collect();
                    let mut description = ReticleDescription::bdc_from_drops(&metric)
                        .map_err(|e| e.to_string())?;
                    // The library labels in meters (the schema is SI); this surface knows
                    // the user's display units, so it relabels with what they typed. The
                    // ladder's first mark is the center, hence the 1-offset.
                    let dist_unit = match units {
                        UnitSystem::Imperial => "yd",
                        UnitSystem::Metric => "m",
                    };
                    for (mark, &(range_display, _, _)) in
                        description.marks.iter_mut().skip(1).zip(parsed.iter())
                    {
                        mark.label = Some(format!("{range_display:.0} {dist_unit}"));
                    }
                    (description, common)
                }
            };
            description.focal_plane = common.focal_plane.into();
            description.reference_magnification = common.reference_mag;
            if let Some(name) = common.name {
                description.name = name;
            }
            description.validate().map_err(|e| e.to_string())?;
            print!(
                "{}",
                format_reticle_description(&description, reticle_format(common.output)?)
            );
            Ok(())
        }

        ReticleAction::Import { file, output } => {
            let json = std::fs::read_to_string(&file)
                .map_err(|e| format!("reading reticle file '{}': {e}", file.display()))?;
            let description = ballistics_engine::reticle_import::import_ventum_reticle(&json)
                .map_err(|e| e.to_string())?;
            // The converter builds but does not validate (matching `mil_grid`/`tree`/
            // `bdc_from_drops`); validating here surfaces a decoration-only import as a clean
            // `NoMarks` error rather than an empty reticle that silently fails downstream.
            description.validate().map_err(|e| e.to_string())?;
            print!(
                "{}",
                format_reticle_description(&description, reticle_format(output)?)
            );
            Ok(())
        }

        ReticleAction::Hold {
            reticle_json,
            profile,
            drop_mil,
            wind_mil,
            range,
            mag,
            velocity,
            bc,
            mass,
            diameter,
            drag_model,
            zero_distance,
            sight_height,
            temperature,
            pressure,
            pressure_type,
            humidity,
            altitude,
            wind_speed,
            wind_direction,
            output,
        } => {
            let format = reticle_format(output)?;
            let profile_data = match profile.as_deref() {
                Some(name) => Some(load_profile(name)?),
                None => None,
            };

            // Reticle source: an explicit file wins over the profile's attached one.
            let description = match (&reticle_json, profile_data.as_ref()) {
                (Some(path), _) => load_reticle_description(path)?,
                (None, Some(data)) => data.reticle.clone().ok_or_else(|| {
                    format!(
                        "profile '{}' has no attached reticle; attach one with \
                         `profile save {} --reticle-json <FILE>`, or pass --reticle-json here",
                        data.name, data.name
                    )
                })?,
                (None, None) => {
                    return Err(
                        "a reticle is required: pass --reticle-json <FILE> or --profile <NAME>"
                            .into(),
                    )
                }
            };

            // Hold source: an explicit angular solution, or one solved at --range. Never
            // both — silently preferring one would hide a contradictory invocation.
            let (hold_drop_mil, hold_wind_mil, solved) = match (drop_mil, range) {
                (Some(_), Some(_)) => {
                    return Err(
                        "--drop-mil and --range are mutually exclusive: give the angular \
                         hold directly, or let --range solve for it"
                            .into(),
                    )
                }
                (Some(drop), None) => (drop, wind_mil.unwrap_or(0.0), None),
                (None, Some(range)) => {
                    if wind_mil.is_some() {
                        return Err(
                            "--wind-mil applies to --drop-mil only; with --range the wind \
                             deflection comes from --wind-speed/--wind-direction"
                                .into(),
                        );
                    }
                    let require = |value: Option<f64>, flag: &str| -> Result<f64, Box<dyn Error>> {
                        value.ok_or_else(|| {
                            format!("--range requires {flag} (directly or from --profile)").into()
                        })
                    };
                    let velocity = require(
                        resolve_param(velocity, &profile_data, |p| p.velocity),
                        "--velocity",
                    )?;
                    let bc = require(resolve_param(bc, &profile_data, |p| p.bc), "--bc")?;
                    let mass = require(resolve_param(mass, &profile_data, |p| p.mass), "--mass")?;
                    let diameter = require(
                        resolve_param(diameter, &profile_data, |p| p.diameter),
                        "--diameter",
                    )?;
                    let zero_distance = require(
                        zero_distance.or_else(|| profile_data.as_ref().and_then(|p| p.zero_distance)),
                        "--zero-distance",
                    )?;
                    // Same fallback `trajectory --saved-profile`/`come-ups --profile` use.
                    let sight_height = sight_height
                        .or_else(|| profile_data.as_ref().and_then(|p| p.sight_height))
                        .unwrap_or(match units {
                            UnitSystem::Imperial => 2.0,
                            UnitSystem::Metric => 50.0,
                        });
                    let temperature = UnitConverter::resolve_temperature(temperature, units)?;
                    // MBA-1416: a declared QNH reduces against this command's own --altitude.
                    let pressure = apply_pressure_mode(
                        UnitConverter::resolve_pressure(pressure, units)?,
                        altitude,
                        pressure_type,
                        units,
                    );

                    let load = HoldCurveLoad {
                        velocity_mps: UnitConverter::velocity_to_metric(velocity, units),
                        bc,
                        mass_kg: UnitConverter::mass_to_metric(mass, units),
                        diameter_m: UnitConverter::diameter_to_metric(diameter, units),
                        drag_model,
                        sight_height_m: UnitConverter::sight_height_to_metric(sight_height, units),
                        zero_distance_m: UnitConverter::distance_to_metric(zero_distance, units),
                        temperature_c: UnitConverter::temperature_to_metric(temperature, units),
                        pressure_hpa: UnitConverter::pressure_to_metric(pressure, units),
                        humidity,
                        altitude_m: UnitConverter::altitude_to_metric(altitude, units),
                        wind_speed_mps: UnitConverter::wind_to_metric(wind_speed, units),
                        wind_direction_deg: wind_direction.degrees,
                    };
                    let range_m = UnitConverter::distance_to_metric(range, units);
                    let curve = HoldCurve::solve(&load, range_m * 1.05)?;
                    let point = curve.at_range(range_m).ok_or_else(|| {
                        format!(
                            "the trajectory does not reach {range} — it was sampled only to {:.1}",
                            UnitConverter::distance_from_metric(
                                curve.max_sampled_range_m(),
                                units
                            )
                        )
                    })?;
                    (point.drop_mil, point.wind_mil, Some(point))
                }
                (None, None) => {
                    return Err(
                        "a firing solution is required: pass --drop-mil (with optional \
                         --wind-mil) or --range"
                            .into(),
                    )
                }
            };

            let hold = hold_point_in_reticle(hold_drop_mil, hold_wind_mil, mag, &description)
                .map_err(|e| e.to_string())?;
            if let (Some(point), OutputFormat::Table) = (solved, output) {
                let (dist_unit, vel_unit) = match units {
                    UnitSystem::Imperial => ("yd", "fps"),
                    UnitSystem::Metric => ("m", "m/s"),
                };
                println!(
                    "Solved at {:.0} {} — {:.1} {} remaining, {:.3} s time of flight\n",
                    UnitConverter::distance_from_metric(point.range_m, units),
                    dist_unit,
                    UnitConverter::velocity_from_metric(point.velocity_mps, units),
                    vel_unit,
                    point.time_s
                );
            }
            print!("{}", format_reticle_hold(&hold, &description, mag, format));
            Ok(())
        }
    }
}

fn run_drag_curve(
    drag_model: DragModel,
    output: OutputFormat,
) -> Result<(), Box<dyn std::error::Error>> {
    // MBA-1426: formatting lives in the library (`drag::format_reference_drag_curve`) and is
    // shared with the browser terminal, so the two surfaces emit identical bytes. Only the PDF
    // rejection stays here, because each surface owns its error convention.
    let format = match output {
        OutputFormat::Table => ballistics_engine::drag::ReferenceDragCurveFormat::Table,
        OutputFormat::Csv => ballistics_engine::drag::ReferenceDragCurveFormat::Csv,
        OutputFormat::Json => ballistics_engine::drag::ReferenceDragCurveFormat::Json,
        OutputFormat::Pdf => {
            return Err("drag-curve has no PDF form; use -o table, -o csv, or -o json".into());
        }
    };
    print!(
        "{}",
        ballistics_engine::drag::format_reference_drag_curve(&drag_model, format)
    );
    Ok(())
}

/// Apply a subcommand's `--pressure-type` to its `--pressure` (MBA-1416).
///
/// The calculator subcommands (`mpbr`, `come-ups`, `range-table`, and the rest) do not run
/// `trajectory`'s full station-conditions resolution — they take `--pressure` as given and hand
/// it straight to `AtmosphericConditions`. Before this, that meant they silently treated every
/// pressure as absolute station pressure, so a weather-report barometer value entered at
/// elevation was wrong by the ISA reduction on every command except `trajectory` and `zero`.
///
/// This applies just the QNH reduction, keyed off the command's own `--altitude`, so `qnh` means
/// the same thing everywhere it is accepted. `Absolute` (and an omitted flag) returns the
/// pressure untouched, which keeps every existing invocation byte-identical.
///
/// `pressure_hpa` is already unit-resolved; `altitude_display` is still in the command's display
/// units (feet imperial / meters metric) and is converted here, because feeding feet to a
/// reduction expecting meters would be a large and completely silent error.
fn apply_pressure_mode(
    pressure_hpa: f64,
    altitude_display: f64,
    mode: Option<PressureReferenceMode>,
    units: UnitSystem,
) -> f64 {
    match mode.unwrap_or(PressureReferenceMode::Absolute) {
        PressureReferenceMode::Absolute => pressure_hpa,
        PressureReferenceMode::Qnh => {
            let altitude_m = UnitConverter::altitude_to_metric(altitude_display, units);
            ballistics_engine::atmosphere::reduce_qnh_to_station_pressure(pressure_hpa, altitude_m)
        }
    }
}

// ============================================================================
// `explain` / `tolerance` (0.33.0 decision-support Task 14, MBA-1345 / MBA-1350)
// ============================================================================

/// Render a solve-json v1 protocol error for CLI display.
///
/// `main` prints its top-level error through `Debug`, which for a plain `String` renders far
/// more readably than a nested typed error's own derived `Debug` would -- so, matching every
/// other subcommand's convention (see `handle_hold_corridor`'s identical note), a protocol
/// error is rendered through its own `Display`-ish accessors into a `String` right here, rather
/// than propagated as `SolveErrorEnvelopeV1` itself.
fn describe_solve_error(e: &SolveErrorEnvelopeV1) -> String {
    match e.error.path() {
        Some(path) => format!("{:?} at {path}: {}", e.error.code, e.error.message),
        None => format!("{:?}: {}", e.error.code, e.error.message),
    }
}

/// Read a solve-json v1 request file, decode it, solve it, and return the RESOLVED request --
/// the one entry point `handle_explain`/`handle_tolerance` both use, so a firing solution is
/// only ever described to this CLI surface one way (a solve-json v1 file), never a second
/// flag-based shape.
fn load_resolved_request(path: &Path) -> Result<ResolvedSolveRequestV1, Box<dyn Error>> {
    let text = fs::read_to_string(path)
        .map_err(|e| format!("could not read solve-json request file {}: {e}", path.display()))?;
    // Every failure mode below is prefixed with `path` too (review I2): `explain` reads TWO
    // files, and without this a decode/solve error is indistinguishable between `--a` and
    // `--b` -- `describe_solve_error` alone has no way to know which file it came from.
    let request = decode_solve_request_v1(&text)
        .map_err(|e| format!("{}: {}", path.display(), describe_solve_error(&e)))?;
    let success = ballistics_engine::solve_v1(request)
        .map_err(|e| format!("{}: {}", path.display(), describe_solve_error(&e)))?;
    Ok(success.resolved_request)
}

/// Canonical kebab-case CLI spelling for one taxonomy axis.
///
/// This is the single source of truth: [`parse_input_axis`] is DERIVED from this match plus
/// [`InputAxis::ALL`], rather than a second, independently hand-maintained match mapping
/// strings back to variants. The match below is exhaustive over `InputAxis`, so a future 33rd
/// variant fails to COMPILE here until it is given a spelling, instead of silently becoming
/// unparseable on the CLI -- see `axis_kebab_names_round_trip_every_member_of_all` below.
fn axis_kebab_name(axis: InputAxis) -> &'static str {
    use InputAxis::*;
    match axis {
        Mass => "mass",
        Diameter => "diameter",
        Length => "length",
        BallisticCoefficient => "ballistic-coefficient",
        TwistRate => "twist-rate",
        TwistDirection => "twist-direction",
        DragModel => "drag-model",
        MuzzleVelocityMps => "muzzle-velocity-mps",
        SightHeight => "sight-height",
        ZeroDistance => "zero-distance",
        ZeroPoiUp => "zero-poi-up",
        ZeroPoiRight => "zero-poi-right",
        SightOffsetLateral => "sight-offset-lateral",
        MuzzleHeight => "muzzle-height",
        MuzzleAngle => "muzzle-angle",
        Altitude => "altitude",
        Temperature => "temperature",
        Pressure => "pressure",
        RelativeHumidity => "relative-humidity",
        Latitude => "latitude",
        WindSpeed => "wind-speed",
        WindDirection => "wind-direction",
        WindVertical => "wind-vertical",
        TargetDistance => "target-distance",
        ShootingAngle => "shooting-angle",
        Cant => "cant",
        ShotAzimuth => "shot-azimuth",
        AimAzimuth => "aim-azimuth",
        TargetHeight => "target-height",
        MagnusEnabled => "magnus-enabled",
        CoriolisEnabled => "coriolis-enabled",
        EnhancedSpinDriftEnabled => "enhanced-spin-drift-enabled",
    }
}

/// Parse one `--axis`/`--domain` axis token (kebab-case) into an [`InputAxis`].
///
/// Derived from [`axis_kebab_name`] plus [`InputAxis::ALL`] rather than a hand-maintained
/// reverse list -- see that function's own doc. An unrecognized name is a hard error listing
/// every accepted spelling, sorted for a stable, greppable message.
fn parse_input_axis(s: &str) -> Result<InputAxis, String> {
    InputAxis::ALL
        .iter()
        .copied()
        .find(|&axis| axis_kebab_name(axis) == s)
        .ok_or_else(|| {
            let mut names: Vec<&str> = InputAxis::ALL.iter().copied().map(axis_kebab_name).collect();
            names.sort_unstable();
            format!("unknown axis '{s}'; accepted axis names are: {}", names.join(", "))
        })
}

/// The physical unit `axis`'s resolved value (and any `--domain` bound for it) is expressed
/// in on this CLI surface -- `""` for a dimensionless or categorical axis.
fn axis_unit_suffix(axis: InputAxis) -> &'static str {
    match axis_meta(axis).kind {
        AxisKind::Continuous { unit, .. } => unit,
        AxisKind::Categorical => "",
    }
}

/// Parse one `--domain AXIS=LO:HI` token into an axis and its (unconverted, axis-native-unit)
/// bounds. Only shape is validated here (a number on each side of one `:`, one `=`); whether
/// the bounds are finite, ordered, and actually bracket the axis's nominal value is
/// `tolerance_envelope`'s own job (`KernelError::InvalidDomain`).
fn parse_domain_arg(s: &str) -> Result<(InputAxis, (f64, f64)), String> {
    let malformed = || format!("invalid --domain '{s}': expected AXIS=LO:HI (e.g. wind-speed=0:20)");
    let (axis_part, range_part) = s.split_once('=').ok_or_else(malformed)?;
    let axis = parse_input_axis(axis_part.trim())?;
    let (lo_str, hi_str) = range_part.split_once(':').ok_or_else(malformed)?;
    let (lo_str, hi_str) = (lo_str.trim(), hi_str.trim());
    let lo: f64 = lo_str
        .parse()
        .map_err(|_| format!("invalid --domain '{s}': lower bound '{lo_str}' is not a number"))?;
    let hi: f64 = hi_str
        .parse()
        .map_err(|_| format!("invalid --domain '{s}': upper bound '{hi_str}' is not a number"))?;
    Ok((axis, (lo, hi)))
}

/// Parse one `error-budget --sigma AXIS=VALUE` token into an axis and its declared one-sigma
/// uncertainty, in the axis's own physical unit.
///
/// The value is validated (finite, non-negative) HERE rather than left to
/// `error_budget_with_target`'s own check: forwarding an invalid sigma to the library would
/// surface `KernelError::NonFinite`'s generic Display text ("axis {axis:?} produced a non-finite
/// result"), which describes a DIFFERENT failure (a computed derivative that came out
/// non-finite) from "the value you typed after '=' is invalid." Naming the flag and the axis
/// directly here avoids that misleading reuse.
fn parse_sigma_arg(s: &str) -> Result<(InputAxis, f64), String> {
    let (axis_part, value_part) = s
        .split_once('=')
        .ok_or_else(|| format!("invalid --sigma '{s}': expected AXIS=VALUE (e.g. wind-speed=1.5)"))?;
    let axis = parse_input_axis(axis_part.trim())?;
    let value_str = value_part.trim();
    let value: f64 = value_str
        .parse()
        .map_err(|_| format!("invalid --sigma '{s}': value '{value_str}' is not a number"))?;
    if !(value.is_finite() && value >= 0.0) {
        return Err(format!(
            "invalid --sigma for axis '{}': {value_str} must be finite and non-negative",
            axis_kebab_name(axis)
        ));
    }
    Ok((axis, value))
}

/// One [`DeltaV1`] as a fixed-width, aligned line -- shared by every group-contribution row,
/// the total, and the interaction remainder so the four numbers line up down the table.
fn format_delta(d: &DeltaV1) -> String {
    format!(
        "drop {:+9.6} m   windage {:+9.6} m   time {:+9.6} s   velocity {:+9.4} m/s",
        d.drop_m, d.windage_m, d.time_s, d.velocity_mps
    )
}

/// Render a [`SolutionDiffReportV1`] as a human-readable table: one block per range, with the
/// interaction remainder on its OWN labelled line (never mistakable for a group's own
/// contribution), then any skipped axes and the report's own stated assumptions.
fn render_explain_table(report: &SolutionDiffReportV1) -> String {
    use std::fmt::Write as _;
    let mut out = String::new();
    let _ = writeln!(out, "explain -- method: {}", report.method);

    for row in &report.rows {
        let _ = writeln!(out);
        let _ = writeln!(out, "range {:.3} m", row.range_m);
        let _ = writeln!(out, "  {:<22} {}", "total", format_delta(&row.total));
        for c in &row.contributions {
            let group_name = format!("{:?}", c.group);
            let _ = writeln!(out, "  {group_name:<22} {}", format_delta(&c.delta));
        }
        // Deliberately its own line, with its own label and a trailing explanation, so it
        // cannot be skimmed as an eighth group contribution.
        let _ = writeln!(
            out,
            "  {:<22} {}   (unexplained by any single group)",
            "interaction remainder",
            format_delta(&row.interaction_remainder)
        );
    }

    if !report.skipped_axes.is_empty() {
        let _ = writeln!(out);
        let _ = writeln!(out, "skipped axes (excluded from that group's swap on both directions):");
        for s in &report.skipped_axes {
            let direction = format!("{:?}", s.direction);
            let group = format!("{:?}", s.group);
            let axis = axis_kebab_name(s.axis);
            let _ = writeln!(out, "  [{direction}] {group} / {axis} -- {}", s.reason);
        }
    }

    let _ = writeln!(out);
    let _ = writeln!(out, "assumptions:");
    for a in &report.assumptions {
        let _ = writeln!(out, "  - {a}");
    }
    out
}

/// `explain` dispatch (MBA-1345).
fn handle_explain(
    a_path: PathBuf,
    b_path: PathBuf,
    ranges_m: Vec<f64>,
    output: OutputFormat,
) -> Result<(), Box<dyn Error>> {
    // Checked before either request is even read: this command runs on the order of 70 solves
    // (see `explain_difference`'s own cost note), so an unsupported output format should fail
    // for free, not after paying for the comparison.
    match output {
        OutputFormat::Csv => return Err("explain has no CSV form; use -o table or -o json".into()),
        OutputFormat::Pdf => return Err("explain has no PDF form; use -o table or -o json".into()),
        OutputFormat::Table | OutputFormat::Json => {}
    }

    let a = load_resolved_request(&a_path)?;
    let b = load_resolved_request(&b_path)?;

    let report = explain_difference(&a, &b, &ranges_m).map_err(|e| e.to_string())?;

    if matches!(output, OutputFormat::Json) {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print!("{}", render_explain_table(&report));
    }
    Ok(())
}

/// One axis's near/far search outcome as a table line -- the five situations a shooter must be
/// able to tell apart (an axis unavailable at all is handled by the caller, one level up, since
/// it never reaches a per-direction search): a real bound, no bound within the configured
/// domain, no measurable effect at all, and (via the caller's own early return before this is
/// called) the nominal itself sitting outside the target.
fn render_tolerance_direction(
    bound: Option<f64>,
    has_no_effect: bool,
    boundary: Option<LimitingBoundaryV1>,
    unit: &str,
) -> String {
    let unit_sp = if unit.is_empty() { "" } else { " " };
    if let Some(v) = bound {
        let edge = boundary.expect("a found bound always carries a limiting boundary");
        format!("bound at {v:.6}{unit_sp}{unit} -- crosses the {edge:?} edge")
    } else if has_no_effect {
        "no measurable effect on the impact (this axis is provably irrelevant here)".to_string()
    } else {
        "no bound within the configured domain (the impact stays inside the target)".to_string()
    }
}

/// Render a [`ToleranceReportV1`] as a human-readable table.
fn render_tolerance_table(report: &ToleranceReportV1) -> String {
    use std::fmt::Write as _;
    let mut out = String::new();
    let _ = writeln!(out, "tolerance -- method: {}", report.method);
    let _ = writeln!(out, "range {:.3} m", report.range_m);

    for axis in &report.axes {
        let _ = writeln!(out);
        let name = axis_kebab_name(axis.axis);
        let unit = axis_unit_suffix(axis.axis);
        let unit_sp = if unit.is_empty() { "" } else { " " };
        let _ = writeln!(
            out,
            "axis {name} (nominal {:.6}{unit_sp}{unit}, target margin {:.4} m)",
            axis.nominal, axis.margin_linear_m
        );
        if !axis.nominal_inside_target {
            let _ = writeln!(
                out,
                "  nominal OUTSIDE target -- target has no positive area; no bound was \
                 searched in either direction"
            );
            continue;
        }
        let _ = writeln!(
            out,
            "  near (toward the domain's lower bound): {}",
            render_tolerance_direction(
                axis.near_bound,
                axis.near_has_no_effect,
                axis.near_limiting_boundary,
                unit
            )
        );
        let _ = writeln!(
            out,
            "  far  (toward the domain's upper bound): {}",
            render_tolerance_direction(
                axis.far_bound,
                axis.far_has_no_effect,
                axis.far_limiting_boundary,
                unit
            )
        );
        // Review I1: `near_has_no_effect`/`far_has_no_effect` can each only be `true` when the
        // matching bound is `None` (`ToleranceAxisV1`'s own doc), so an axis with NO EFFECT IN
        // EITHER DIRECTION also reads `unbounded_in_domain == true` -- the exact "no effect" vs.
        // "unbounded" conflation this pair of fields exists to prevent (module doc,
        // "`TargetDistance` cannot answer..."). Printing "stays inside" there would read as
        // reassurance about a change that provably does nothing at all, undoing the very
        // distinction the two lines above it just made. Only print the summary when at least
        // one direction genuinely has an effect; the both-no-effect case is already fully
        // stated by those two per-direction lines and needs no "stays inside" recap.
        if axis.unbounded_in_domain && !(axis.near_has_no_effect && axis.far_has_no_effect) {
            let _ = writeln!(
                out,
                "  unbounded in domain: the impact stays inside the target across the whole \
                 configured domain"
            );
        }
    }

    if !report.unavailable_axes.is_empty() {
        let _ = writeln!(out);
        let _ = writeln!(out, "unavailable axes (could not be searched at all):");
        for u in &report.unavailable_axes {
            let name = axis_kebab_name(u.axis);
            let code = format!("{:?}", u.code);
            let _ = writeln!(out, "  {name} [{code}] -- {}", u.reason);
        }
    }

    let _ = writeln!(out);
    let _ = writeln!(out, "assumptions:");
    for a in &report.assumptions {
        let _ = writeln!(out, "  - {a}");
    }
    out
}

/// `tolerance` dispatch (MBA-1350).
#[allow(
    clippy::too_many_arguments,
    reason = "flat arguments mirror the stable Clap command shape"
)]
fn handle_tolerance(
    request_path: PathBuf,
    range_m: f64,
    target: String,
    axes_raw: Vec<String>,
    domains_raw: Vec<String>,
    units: UnitSystem,
    output: OutputFormat,
) -> Result<(), Box<dyn Error>> {
    match output {
        OutputFormat::Csv => return Err("tolerance has no CSV form; use -o table or -o json".into()),
        OutputFormat::Pdf => return Err("tolerance has no PDF form; use -o table or -o json".into()),
        OutputFormat::Table | OutputFormat::Json => {}
    }

    let axes: Vec<InputAxis> = axes_raw
        .iter()
        .map(|s| parse_input_axis(s))
        .collect::<Result<_, _>>()?;
    for (i, &axis) in axes.iter().enumerate() {
        if axes[..i].contains(&axis) {
            return Err(format!("--axis {} was given more than once", axis_kebab_name(axis)).into());
        }
    }

    let mut domains: Vec<(InputAxis, (f64, f64))> = Vec::with_capacity(domains_raw.len());
    for raw in &domains_raw {
        let (axis, bounds) = parse_domain_arg(raw)?;
        if domains.iter().any(|(a, _)| *a == axis) {
            return Err(format!(
                "--domain for axis '{}' was given more than once",
                axis_kebab_name(axis)
            )
            .into());
        }
        domains.push((axis, bounds));
    }
    // tolerance_envelope never invents a domain (a silent default would misrepresent how far an
    // axis was actually searched), so the CLI insists every --axis has a matching --domain up
    // front, naming the specific axis and the flag syntax -- clearer than forwarding
    // KernelError::InvalidDomain's "no domain was configured for this axis", which cannot
    // mention --domain at all.
    for &axis in &axes {
        if !domains.iter().any(|(a, _)| *a == axis) {
            let unit = axis_unit_suffix(axis);
            let hint = if unit.is_empty() { String::new() } else { format!(" (in {unit})") };
            let name = axis_kebab_name(axis);
            return Err(format!(
                "--axis {name} has no matching --domain; supply one as --domain {name}=LO:HI{hint}"
            )
            .into());
        }
    }
    for (axis, _) in &domains {
        if !axes.contains(axis) {
            return Err(format!(
                "--domain was given for axis '{}', which was not requested with --axis",
                axis_kebab_name(*axis)
            )
            .into());
        }
    }

    let resolved = load_resolved_request(&request_path)?;

    let target_spec = parse_target_spec(&target, units).map_err(|e| e.to_string())?;
    let geometry = match target_spec {
        TargetSpec::Rect { width_m, height_m } => TargetGeometryV1::Rect { width_m, height_m },
        TargetSpec::Circle { diameter_m } => TargetGeometryV1::Circle { radius_m: diameter_m / 2.0 },
    };

    let report = tolerance_envelope(&resolved, &axes, range_m, geometry, &domains)
        .map_err(|e| e.to_string())?;

    if matches!(output, OutputFormat::Json) {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print!("{}", render_tolerance_table(&report));
    }
    Ok(())
}

/// Render an [`ErrorBudgetReportV1`] as a human-readable table: one block per range with the
/// impact spread, the ranked source list (variance share as a percentage; the finite-difference
/// scheme is named only when it is NOT the ordinary central one; the per-source hit-probability
/// gain only when the report carries one at all), and the row's own priority statement on its
/// own line -- then, once (the same list applies to every row), any declared source the kernel
/// could not evaluate at all, with its reason, so a source that could not be measured never
/// reads the same as a source that measured zero.
fn render_error_budget_table(report: &ErrorBudgetReportV1) -> String {
    use std::fmt::Write as _;
    let mut out = String::new();
    let _ = writeln!(out, "error-budget -- method: {}", report.method);

    for row in &report.rows {
        let _ = writeln!(out);
        let _ = writeln!(out, "range {:.3} m", row.range_m);
        let _ = writeln!(
            out,
            "  impact spread: sigma_drop {:.6} m   sigma_windage {:.6} m   covariance {:.6} m^2",
            row.sigma_drop_m, row.sigma_windage_m, row.covariance_m2
        );
        let _ = writeln!(
            out,
            "  95% ellipse: semi-major {:.6} m   semi-minor {:.6} m   area {:.6} m^2",
            row.ellipse_95.semi_major_m, row.ellipse_95.semi_minor_m, row.ellipse_95.area_m2
        );
        if let Some(p_hit) = row.p_hit {
            let _ = writeln!(out, "  p_hit: {:.1}%", p_hit * 100.0);
        }
        if !row.sources.is_empty() {
            let _ = writeln!(out, "  ranked sources (share of impact variance):");
            for (i, s) in row.sources.iter().enumerate() {
                let name = axis_kebab_name(s.axis);
                let scheme_note = if s.scheme == DifferenceScheme::Central {
                    String::new()
                } else {
                    format!("   [{:?}]", s.scheme)
                };
                let gain_note = match s.p_hit_gain_if_perfect {
                    Some(gain) => format!("   gain if perfected: p_hit +{:.3}%", gain * 100.0),
                    None => String::new(),
                };
                let _ = writeln!(
                    out,
                    "    {:>2}. {:<28} {:>6.1}%{scheme_note}{gain_note}",
                    i + 1,
                    name,
                    s.variance_share * 100.0
                );
            }
        }
        let _ = writeln!(out, "  priority: {}", row.priority_statement);
    }

    if !report.unavailable_sources.is_empty() {
        let _ = writeln!(out);
        let _ = writeln!(out, "unavailable sources (could not be evaluated at all):");
        for u in &report.unavailable_sources {
            let name = axis_kebab_name(u.axis);
            let code = format!("{:?}", u.code);
            let _ = writeln!(out, "  {name} (sigma {:.6}) [{code}] -- {}", u.sigma, u.reason);
        }
    }

    let _ = writeln!(out);
    let _ = writeln!(out, "assumptions:");
    for a in &report.assumptions {
        let _ = writeln!(out, "  - {a}");
    }
    out
}

/// `error-budget` dispatch (MBA-1347).
fn handle_error_budget(
    request_path: PathBuf,
    ranges_m: Vec<f64>,
    sigmas_raw: Vec<String>,
    target: Option<String>,
    units: UnitSystem,
    output: OutputFormat,
) -> Result<(), Box<dyn Error>> {
    match output {
        OutputFormat::Csv => {
            return Err("error-budget has no CSV form; use -o table or -o json".into())
        }
        OutputFormat::Pdf => {
            return Err("error-budget has no PDF form; use -o table or -o json".into())
        }
        OutputFormat::Table | OutputFormat::Json => {}
    }

    // Parsed and de-duplicated up front, before the request is even read -- the same ordering
    // `handle_tolerance` uses for --axis, and for the identical reason: a duplicate declaration
    // would double-count that axis's variance and corrupt its own leave-one-out counterfactual,
    // so it is rejected by name rather than silently accepted (and cheaper to reject before
    // paying for a solve).
    let mut sources: Vec<(InputAxis, f64)> = Vec::with_capacity(sigmas_raw.len());
    for raw in &sigmas_raw {
        let (axis, sigma) = parse_sigma_arg(raw)?;
        if sources.iter().any(|&(a, _)| a == axis) {
            return Err(format!(
                "--sigma for axis '{}' was given more than once",
                axis_kebab_name(axis)
            )
            .into());
        }
        sources.push((axis, sigma));
    }

    let resolved = load_resolved_request(&request_path)?;

    // Mirrors `handle_tolerance`'s ordering: the target spec is parsed after the request is
    // loaded (it does not depend on it, but this keeps both handlers' stage order identical).
    let geometry = target
        .map(|spec| {
            parse_target_spec(&spec, units).map(|target_spec| match target_spec {
                TargetSpec::Rect { width_m, height_m } => TargetGeometryV1::Rect { width_m, height_m },
                TargetSpec::Circle { diameter_m } => {
                    TargetGeometryV1::Circle { radius_m: diameter_m / 2.0 }
                }
            })
        })
        .transpose()
        .map_err(|e| e.to_string())?;

    let report = error_budget_with_target(&resolved, &sources, &ranges_m, geometry)
        .map_err(|e| e.to_string())?;

    if matches!(output, OutputFormat::Json) {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print!("{}", render_error_budget_table(&report));
    }
    Ok(())
}

#[cfg(test)]
mod decision_support_axis_tests {
    use super::*;

    /// A future 33rd `InputAxis` variant cannot silently become unparseable: `axis_kebab_name`
    /// is an exhaustive match (a compile error catches an unhandled variant), and this pins
    /// down that `parse_input_axis` -- built from that same function plus `InputAxis::ALL` --
    /// actually round-trips every one of them, not just the ones a hand-picked sample covers.
    #[test]
    fn axis_kebab_names_round_trip_every_member_of_all() {
        for &axis in InputAxis::ALL {
            let name = axis_kebab_name(axis);
            assert_eq!(
                parse_input_axis(name),
                Ok(axis),
                "'{name}' (from {axis:?}) did not parse back to the same axis"
            );
        }
    }

    /// Every accepted name is unique -- otherwise two different axes would silently share one
    /// CLI spelling and `parse_input_axis` would always return whichever comes first in `ALL`.
    #[test]
    fn every_axis_kebab_name_is_unique() {
        let mut names: Vec<&str> = InputAxis::ALL.iter().copied().map(axis_kebab_name).collect();
        let before = names.len();
        names.sort_unstable();
        names.dedup();
        assert_eq!(names.len(), before, "two axes share a kebab-case name");
    }

    #[test]
    fn unknown_axis_lists_every_accepted_name() {
        let err = parse_input_axis("not-a-real-axis").unwrap_err();
        assert!(err.contains("unknown axis 'not-a-real-axis'"), "{err}");
        for &axis in InputAxis::ALL {
            assert!(
                err.contains(axis_kebab_name(axis)),
                "error is missing '{}': {err}",
                axis_kebab_name(axis)
            );
        }
    }

    #[test]
    fn domain_arg_parses_axis_and_bounds() {
        assert_eq!(
            parse_domain_arg("wind-speed=0:20"),
            Ok((InputAxis::WindSpeed, (0.0, 20.0)))
        );
        assert_eq!(
            parse_domain_arg("cant=-0.05:0.05"),
            Ok((InputAxis::Cant, (-0.05, 0.05)))
        );
    }

    #[test]
    fn domain_arg_rejects_malformed_tokens() {
        assert!(parse_domain_arg("wind-speed").is_err(), "missing '='");
        assert!(parse_domain_arg("wind-speed=0").is_err(), "missing ':'");
        assert!(parse_domain_arg("wind-speed=lo:20").is_err(), "non-numeric lower bound");
        assert!(parse_domain_arg("nope=0:20").is_err(), "unknown axis");
    }

    #[test]
    fn sigma_arg_parses_axis_and_value() {
        assert_eq!(parse_sigma_arg("wind-speed=1.5"), Ok((InputAxis::WindSpeed, 1.5)));
        assert_eq!(
            parse_sigma_arg("muzzle-velocity-mps=5.0"),
            Ok((InputAxis::MuzzleVelocityMps, 5.0))
        );
        // A zero sigma is a legitimate declaration (the source is real but currently trusted
        // exactly) -- it must parse, not be rejected as if it were missing.
        assert_eq!(parse_sigma_arg("cant=0"), Ok((InputAxis::Cant, 0.0)));
    }

    #[test]
    fn sigma_arg_rejects_malformed_unknown_or_invalid_tokens() {
        assert!(parse_sigma_arg("wind-speed").is_err(), "missing '='");
        assert!(parse_sigma_arg("nope=1.5").is_err(), "unknown axis");
        assert!(parse_sigma_arg("wind-speed=abc").is_err(), "non-numeric value");
        let negative = parse_sigma_arg("wind-speed=-1.0").unwrap_err();
        assert!(negative.contains("wind-speed"), "{negative}");
        let non_finite = parse_sigma_arg("wind-speed=NaN").unwrap_err();
        assert!(non_finite.contains("wind-speed"), "{non_finite}");
        let infinite = parse_sigma_arg("wind-speed=inf").unwrap_err();
        assert!(infinite.contains("wind-speed"), "{infinite}");
    }
}

#[cfg(test)]
mod decision_support_render_tests {
    use super::*;
    use ballistics_engine::error_budget::{
        Ellipse95V1, ErrorBudgetRowV1, SourceContributionV1, UnavailableReasonCodeV1,
        UnavailableSourceV1,
    };
    use ballistics_engine::tolerance::{ToleranceAxisV1, UnavailableAxisV1};

    /// Delta #3's "nominal outside target" situation cannot be driven through this CLI's own
    /// `--target` flag at all: `parse_target_spec` (`wind_scenarios.rs`) rejects a non-positive
    /// width/height/diameter at the STRING-parsing stage, before a `TargetGeometryV1` is even
    /// built, and `nominal_inside_target` can only be `false` for a target with no positive
    /// area (`tolerance.rs`'s own module doc, "The central hazard") -- so this CLI can never
    /// hand `tolerance_envelope` a degenerate target to reproduce it end-to-end (see the
    /// task-14 report). The renderer must still get it right, so this builds a
    /// `ToleranceReportV1` by hand -- covering all five situations in one table, with a
    /// distinct marker phrase expected EXACTLY once per situation -- and checks
    /// `render_tolerance_table` directly. A mutation that rendered two situations identically
    /// (e.g. collapsing "no measurable effect" into the generic "no bound" text) would change a
    /// count from 1 to 0 or 2, not just move text around.
    #[test]
    fn table_distinguishes_all_five_axis_situations() {
        let report = ToleranceReportV1 {
            schema_version: 1,
            method: "one_variable_deterministic_bisection".to_string(),
            assumptions: vec!["test assumption".to_string()],
            range_m: 600.0,
            unavailable_axes: vec![UnavailableAxisV1 {
                axis: InputAxis::MagnusEnabled,
                code: UnavailableReasonCodeV1::CategoricalAxis,
                reason: "this axis is categorical and cannot be assigned a domain".to_string(),
            }],
            axes: vec![
                // 1. A real bound in both directions.
                ToleranceAxisV1 {
                    axis: InputAxis::WindSpeed,
                    nominal: 3.0,
                    nominal_inside_target: true,
                    near_bound: Some(1.2),
                    far_bound: Some(5.4),
                    near_limiting_boundary: Some(LimitingBoundaryV1::Left),
                    far_limiting_boundary: Some(LimitingBoundaryV1::Right),
                    unbounded_in_domain: false,
                    near_has_no_effect: false,
                    far_has_no_effect: false,
                    margin_linear_m: 0.15,
                },
                // 2. No bound within the domain, but the axis does move the impact.
                ToleranceAxisV1 {
                    axis: InputAxis::WindVertical,
                    nominal: 0.0,
                    nominal_inside_target: true,
                    near_bound: None,
                    far_bound: None,
                    near_limiting_boundary: None,
                    far_limiting_boundary: None,
                    unbounded_in_domain: true,
                    near_has_no_effect: false,
                    far_has_no_effect: false,
                    margin_linear_m: 0.15,
                },
                // 3. No measurable effect at all -- same `None`/`None` shape as #2, must render
                // differently.
                ToleranceAxisV1 {
                    axis: InputAxis::TargetDistance,
                    nominal: 900.0,
                    nominal_inside_target: true,
                    near_bound: None,
                    far_bound: None,
                    near_limiting_boundary: None,
                    far_limiting_boundary: None,
                    unbounded_in_domain: true,
                    near_has_no_effect: true,
                    far_has_no_effect: true,
                    margin_linear_m: 0.15,
                },
                // 4. Nominal outside the target -- structurally unreachable via the CLI (see
                // this test's own doc comment), but the renderer must still handle it.
                ToleranceAxisV1 {
                    axis: InputAxis::Cant,
                    nominal: 0.01,
                    nominal_inside_target: false,
                    near_bound: None,
                    far_bound: None,
                    near_limiting_boundary: None,
                    far_limiting_boundary: None,
                    unbounded_in_domain: false,
                    near_has_no_effect: false,
                    far_has_no_effect: false,
                    margin_linear_m: 0.0,
                },
            ],
        };

        let table = render_tolerance_table(&report);

        assert_eq!(table.matches("crosses the Left edge").count(), 1, "{table}");
        assert_eq!(table.matches("crosses the Right edge").count(), 1, "{table}");
        // Each of these fires once per DIRECTION (near and far), both directions being
        // identical in this synthetic fixture -- so 2, not 1, per axis; the point of the count
        // is that it is the SAME 2 either way, never mixed between the two axes below.
        assert_eq!(
            table.matches("no bound within the configured domain").count(),
            2,
            "exactly one axis (wind-vertical), both directions, is merely unbounded: {table}"
        );
        assert_eq!(
            table.matches("no measurable effect on the impact").count(),
            2,
            "exactly one axis (target-distance), both directions, has no effect -- must not \
             share text with the merely-unbounded axis: {table}"
        );
        assert_eq!(
            table.matches("nominal OUTSIDE target").count(),
            1,
            "exactly one axis (cant) has its nominal outside the target: {table}"
        );
        assert_eq!(
            table.matches("could not be searched at all").count(),
            1,
            "exactly one axis (magnus-enabled) is structurally unavailable: {table}"
        );
        // Review I1: the "unbounded in domain" summary is a RECAP of a genuine effect, not a
        // blanket consequence of `unbounded_in_domain` alone -- target-distance is ALSO
        // `unbounded_in_domain: true` (both bounds `None`), but both directions are
        // `*_has_no_effect: true`, so it must NOT get the summary line (that would read as
        // reassurance about a change that provably does nothing). Exactly one summary line is
        // expected: wind-vertical's.
        assert_eq!(
            table.matches("unbounded in domain:").count(),
            1,
            "only wind-vertical (unbounded WITH effect) may print the summary line -- \
             target-distance (unbounded with NO effect) must not: {table}"
        );

        // Each marker attaches to the RIGHT axis, not just somewhere in the output.
        assert!(table.contains("axis wind-speed"), "{table}");
        assert!(table.contains("axis wind-vertical"), "{table}");
        assert!(table.contains("axis target-distance"), "{table}");
        assert!(table.contains("axis cant"), "{table}");
        assert!(table.contains("magnus-enabled ["), "{table}");
    }

    /// Zero-cost (no solve -- the report is built by hand) pin of `render_error_budget_table`'s
    /// MUST-render properties from the task-15 brief's corrections: the ranked list shows
    /// variance share as a percentage and names a scheme only when it is NOT central; the
    /// p_hit/per-source gain columns appear because this report carries a target; and an
    /// unavailable source is named with its reason while staying out of the ranked list.
    #[test]
    fn error_budget_table_renders_ranked_sources_gain_and_unavailable_sources() {
        let report = ErrorBudgetReportV1 {
            schema_version: 1,
            method: "central_difference_first_order_propagation_gl20_panelled_pm6sigma"
                .to_string(),
            assumptions: vec!["Declared sources are treated as independent.".to_string()],
            unavailable_sources: vec![UnavailableSourceV1 {
                axis: InputAxis::Altitude,
                sigma: 50.0,
                code: UnavailableReasonCodeV1::AxisUnsupportedForRequest,
                reason: "the original request declared a QNH pressure_reference".to_string(),
            }],
            rows: vec![ErrorBudgetRowV1 {
                range_m: 600.0,
                sigma_drop_m: 0.2,
                sigma_windage_m: 0.3,
                covariance_m2: 0.01,
                ellipse_95: Ellipse95V1 {
                    semi_major_m: 0.5,
                    semi_minor_m: 0.1,
                    rotation_rad: 0.0,
                    area_m2: 0.157,
                },
                p_hit: Some(0.873),
                sources: vec![
                    SourceContributionV1 {
                        axis: InputAxis::WindSpeed,
                        sigma: 1.5,
                        d_drop_d_x: 0.0,
                        d_windage_d_x: 0.2,
                        scheme: DifferenceScheme::ForwardOneSided,
                        variance_share: 0.623,
                        ellipse_area_reduction_m2: 0.157,
                        p_hit_gain_if_perfect: Some(0.4416),
                    },
                    SourceContributionV1 {
                        axis: InputAxis::MuzzleVelocityMps,
                        sigma: 5.0,
                        d_drop_d_x: 0.001,
                        d_windage_d_x: 0.0,
                        scheme: DifferenceScheme::Central,
                        variance_share: 0.377,
                        ellipse_area_reduction_m2: 0.157,
                        p_hit_gain_if_perfect: Some(0.00008),
                    },
                ],
                priority_statement: "WindSpeed dominates at 600 m (62.3% of impact variance)."
                    .to_string(),
            }],
        };

        let table = render_error_budget_table(&report);

        // The ranked list: both sources present, share rendered as a percentage. This test does
        // not re-sort (that is `error_budget_with_target`'s own job, covered by its library test
        // suite) -- the renderer must not reorder or drop either one.
        assert!(table.contains("wind-speed"), "{table}");
        assert!(table.contains("62.3%"), "{table}");
        assert!(table.contains("muzzle-velocity-mps"), "{table}");
        assert!(table.contains("37.7%"), "{table}");

        // The scheme is named ONLY for the non-central source.
        assert_eq!(table.matches("ForwardOneSided").count(), 1, "{table}");
        assert!(!table.contains("[Central]"), "{table}");

        // p_hit and the per-source gain-if-perfected column are both present because this
        // report carries a target -- including wind-speed's large gain and
        // muzzle-velocity-mps's tiny one, which a coarser percentage format would round to the
        // same "0.0%" and erase the very distinction this column exists to show (see
        // `SourceContributionV1::p_hit_gain_if_perfect`'s own doc comment).
        assert!(table.contains("p_hit: 87.3%"), "{table}");
        assert_eq!(table.matches("gain if perfected").count(), 2, "{table}");
        assert!(table.contains("44.160%"), "wind-speed's own large gain: {table}");
        assert!(table.contains("0.008%"), "muzzle-velocity-mps's own tiny gain: {table}");

        // The unavailable source is named, with its reason, and never inside the ranked list.
        assert!(table.contains("unavailable sources"), "{table}");
        assert!(table.contains("altitude"), "{table}");
        assert!(table.contains("QNH"), "{table}");
        let ranked_section = table.split("unavailable sources").next().unwrap();
        assert!(
            !ranked_section.contains("altitude"),
            "an unavailable source must not appear in the ranked list: {table}"
        );

        // The priority statement is rendered on its own line.
        assert!(table.contains("priority: WindSpeed dominates"), "{table}");
    }

    /// A report with no target at all (`error_budget`'s own `None` wrapper) must render NEITHER
    /// `p_hit` NOR any per-source gain -- never a fabricated number standing in for the real
    /// absence. Complements the JSON-shaped check already made by
    /// `error_budget_table_shows_p_hit_and_gain_only_with_a_target` in
    /// `tests/decision_support_cli.rs`.
    #[test]
    fn error_budget_table_omits_p_hit_and_gain_without_a_target() {
        let report = ErrorBudgetReportV1 {
            schema_version: 1,
            method: "central_difference_first_order_propagation".to_string(),
            assumptions: vec!["Declared sources are treated as independent.".to_string()],
            unavailable_sources: vec![],
            rows: vec![ErrorBudgetRowV1 {
                range_m: 600.0,
                sigma_drop_m: 0.2,
                sigma_windage_m: 0.3,
                covariance_m2: 0.01,
                ellipse_95: Ellipse95V1 {
                    semi_major_m: 0.5,
                    semi_minor_m: 0.1,
                    rotation_rad: 0.0,
                    area_m2: 0.157,
                },
                p_hit: None,
                sources: vec![SourceContributionV1 {
                    axis: InputAxis::WindSpeed,
                    sigma: 1.5,
                    d_drop_d_x: 0.0,
                    d_windage_d_x: 0.2,
                    scheme: DifferenceScheme::Central,
                    variance_share: 1.0,
                    ellipse_area_reduction_m2: 0.0,
                    p_hit_gain_if_perfect: None,
                }],
                priority_statement: "WindSpeed dominates at 600 m (100.0% of impact variance)."
                    .to_string(),
            }],
        };

        let table = render_error_budget_table(&report);
        assert!(!table.contains("p_hit:"), "{table}");
        assert!(!table.contains("gain if perfected"), "{table}");
        assert!(table.contains("wind-speed"), "{table}");
        assert!(table.contains("100.0%"), "{table}");
    }
}

// ============================================================================================
// MBA-1348 Plan B Task 6: `dial-plan` -- the `plan_corrections` CLI surface
// ============================================================================================

/// `Axis::Elevation`/`Axis::Windage` as the lowercase word this table uses everywhere else
/// (matches `axis_kebab_name`'s lowercase convention for the unrelated `InputAxis`).
fn dial_plan_axis_label(axis: Axis) -> &'static str {
    match axis {
        Axis::Elevation => "elevation",
        Axis::Windage => "windage",
    }
}

/// `AxisInstruction::direction` as the shouted word a shooter reads off a dial under time
/// pressure -- deliberately uppercase, unlike `dial_plan_axis_label`, so it reads as an
/// instruction rather than a label.
fn dial_plan_direction_word(direction: Direction) -> &'static str {
    match direction {
        Direction::Up => "UP",
        Direction::Down => "DOWN",
        Direction::Left => "LEFT",
        Direction::Right => "RIGHT",
    }
}

/// `Strategy`'s table label -- the same snake_case spelling `#[serde(rename_all =
/// "snake_case")]` gives it on the wire, so the table and `-o json` never disagree about a
/// strategy's name.
fn dial_plan_strategy_label(strategy: Strategy) -> &'static str {
    match strategy {
        Strategy::DialAll => "dial_all",
        Strategy::HoldAll => "hold_all",
        Strategy::Hybrid => "hybrid",
    }
}

/// Render a [`DialPlanReportV1`] as a human-readable table (MBA-1348 Task 6): one block per
/// ranked plan (best first -- see `plan_corrections`' own ranking doc) with a strategy header
/// naming feasibility, one instruction line per axis (direction, delta clicks, a revolution
/// annotation when the turret declares `clicks_per_revolution`, and the TRUE angular hold), a
/// residual line (both axes' angular residual plus the RSS linear miss at range), and any
/// limit violations this plan hit. A violation is disclosed even on a FEASIBLE plan -- a
/// `Hybrid` plan's own travel clamp is recorded but does not gate ITS feasibility, see
/// `plan_corrections`' "Honesty" doc section -- and an infeasible plan is rendered exactly
/// like a feasible one, never hidden: this table (and the command's own exit code) treats a
/// "this doesn't fit" conclusion as a normal, successful result.
fn render_dial_plan_table(report: &DialPlanReportV1) -> String {
    use std::fmt::Write as _;
    let mut out = String::new();
    let _ = writeln!(out, "dial-plan -- method: {}", report.method);
    let _ = writeln!(out, "range: {:.3} m", report.range_m);

    for (i, plan) in report.plans.iter().enumerate() {
        let _ = writeln!(out);
        let feasible_word = if plan.feasible { "FEASIBLE" } else { "INFEASIBLE" };
        let _ = writeln!(
            out,
            "#{} strategy: {} [{feasible_word}]",
            i + 1,
            dial_plan_strategy_label(plan.strategy)
        );

        for instr in &plan.instructions {
            let axis_label = dial_plan_axis_label(instr.axis);
            let dir_word = dial_plan_direction_word(instr.direction);
            let revolution = match instr.end_revolution {
                Some((revs, clicks_in_rev)) => {
                    format!(" (end at rev {revs} + {clicks_in_rev} clicks)")
                }
                None => String::new(),
            };
            let _ = writeln!(
                out,
                "  {axis_label}: dial {dir_word} {} clicks{revolution}; hold {:.3} mil",
                instr.delta_clicks.abs(),
                instr.hold_mil
            );
        }

        let _ = writeln!(
            out,
            "  residual: elevation {:.3} mil, windage {:.3} mil -> {:.3} m at {:.3} m",
            plan.instructions[0].residual_mil,
            plan.instructions[1].residual_mil,
            plan.residual_linear_at_range_m,
            report.range_m
        );

        for v in &plan.limits_hit {
            let axis_label = dial_plan_axis_label(v.axis);
            let kind = format!("{:?}", v.kind);
            let available = match v.available_mil {
                Some(a) => format!("available {a:.3} mil"),
                None => "no data declared for this axis".to_string(),
            };
            let _ = writeln!(
                out,
                "  limit: {axis_label} {kind} -- needed {:.3} mil, {available}",
                v.needed_mil
            );
        }
    }

    let _ = writeln!(out);
    let _ = writeln!(out, "assumptions:");
    for a in &report.assumptions {
        let _ = writeln!(out, "  - {a}");
    }
    out
}

/// `dial-plan` dispatch (MBA-1348 Task 6): resolves the optic from either `--profile` or the
/// inline turret/hold flags (mutually exclusive), resolves the TRUE angular correction from
/// `--elevation`/`--windage` (at least one required), and hands both to `plan_corrections`.
/// Unlike every calculator subcommand in this file, this runs no solve at all -- the
/// correction is a direct input -- so this handler is pure, instant arithmetic.
#[allow(
    clippy::too_many_arguments,
    reason = "flat arguments mirror the stable dial-plan CLI command shape"
)]
fn handle_dial_plan(
    elevation: Option<f64>,
    windage: Option<f64>,
    range: f64,
    profile: Option<String>,
    elevation_click: Option<String>,
    windage_click: Option<String>,
    clicks_per_rev: Option<u32>,
    zero_stop: Option<bool>,
    travel_up: Option<f64>,
    travel_down: Option<f64>,
    windage_travel_left: Option<f64>,
    windage_travel_right: Option<f64>,
    hold_up: Option<f64>,
    hold_down: Option<f64>,
    hold_left: Option<f64>,
    hold_right: Option<f64>,
    turret_elev: Option<f64>,
    turret_wind: Option<f64>,
    prefer_hold: bool,
    max_hold: Option<f64>,
    units: UnitSystem,
    output: OutputFormat,
) -> Result<(), Box<dyn Error>> {
    match output {
        OutputFormat::Csv => {
            return Err("dial-plan has no CSV form; use -o table or -o json".into())
        }
        OutputFormat::Pdf => {
            return Err("dial-plan has no PDF form; use -o table or -o json".into())
        }
        OutputFormat::Table | OutputFormat::Json => {}
    }

    if elevation.is_none() && windage.is_none() {
        return Err("at least one of --elevation or --windage is required".into());
    }

    let inline_flag_given = elevation_click.is_some()
        || windage_click.is_some()
        || clicks_per_rev.is_some()
        || zero_stop.is_some()
        || travel_up.is_some()
        || travel_down.is_some()
        || windage_travel_left.is_some()
        || windage_travel_right.is_some()
        || hold_up.is_some()
        || hold_down.is_some()
        || hold_left.is_some()
        || hold_right.is_some()
        || turret_elev.is_some()
        || turret_wind.is_some();

    if profile.is_some() && inline_flag_given {
        return Err(
            "--profile cannot be combined with inline optic flags (--elevation-click and the \
             rest of the turret/hold flags) -- choose one source for the optic"
                .into(),
        );
    }

    let (optic, elevation_cf, windage_cf) = match profile {
        Some(name) => {
            let data = load_profile(&name)?;
            let optic = data
                .optic_profile()
                .map_err(|e| format!("profile '{name}': {e}"))?
                .ok_or_else(|| {
                    format!(
                        "profile '{name}' has no optic (turret/click) data saved -- save one \
                         with `profile save --elevation-click <SIZE><UNIT>`"
                    )
                })?;
            (optic, data.elevation_cf.unwrap_or(1.0), data.windage_cf.unwrap_or(1.0))
        }
        None => {
            let Some(elev_str) = elevation_click.as_deref() else {
                return Err(
                    "either --profile <NAME> or --elevation-click <SIZE><UNIT> is required to \
                     define the optic"
                        .into(),
                );
            };
            let elevation_click_v = parse_click_value(elev_str)?;
            let windage_click_v = match windage_click.as_deref() {
                Some(s) => parse_click_value(s)?,
                None => elevation_click_v,
            };
            let elevation_travel =
                require_angular_pair("--travel-up", travel_up, "--travel-down", travel_down)?
                    .map(|(up, down)| TravelLimits { up_mil: up, down_mil: down });
            let windage_travel = require_angular_pair(
                "--windage-travel-left",
                windage_travel_left,
                "--windage-travel-right",
                windage_travel_right,
            )?
            .map(|(left, right)| TravelLimits { down_mil: left, up_mil: right });
            let turret_state =
                require_angular_pair("--turret-elev", turret_elev, "--turret-wind", turret_wind)?
                    .map(|(elevation_mil, windage_mil)| TurretState {
                        elevation_mil,
                        windage_mil,
                    });
            let reticle_hold_bounds =
                require_hold_bounds(hold_up, hold_down, hold_left, hold_right)?;
            let optic = OpticProfile {
                elevation_click: elevation_click_v,
                windage_click: windage_click_v,
                clicks_per_revolution: clicks_per_rev,
                zero_stop: zero_stop.unwrap_or(false),
                elevation_travel,
                windage_travel,
                turret_state,
                reticle_hold_bounds,
            };
            (optic, 1.0, 1.0)
        }
    };

    let range_m = UnitConverter::distance_to_metric(range, units);
    let correction = AngularCorrection {
        elevation_mil: elevation.unwrap_or(0.0),
        windage_mil: windage.unwrap_or(0.0),
    };
    let prefs = Preferences { prefer_hold, max_hold_mil: max_hold };

    let report = plan_corrections(correction, &optic, range_m, elevation_cf, windage_cf, &prefs)
        .map_err(|e| e.to_string())?;

    if matches!(output, OutputFormat::Json) {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print!("{}", render_dial_plan_table(&report));
    }
    Ok(())
}

// ============================================================================
// Adaptive Range Card (MBA-1351, 0.33.0 decision-support Plan B Task 12)
// ============================================================================

/// Default reconstruction-error budget when `--elevation-budget`/`--windage-budget` is
/// omitted: half the profile's click on that axis -- the honest floor `adaptive_card`'s own
/// assumptions already document (a tighter budget is reported `budget_met: false`, never
/// silently relaxed) -- or 0.1 TRUE mil when no optic click is known. Returned in TRUE mil;
/// the caller scales into the chosen `--adjustment` unit exactly like a supplied
/// `--elevation-budget`/`--windage-budget` string is (`parse_angular_mil` then the unit
/// factor), so an explicit budget and this default land in the same space.
fn adaptive_card_default_budget_mil(click: Option<&ClickValue>) -> f64 {
    match click {
        Some(c) => click_size_mil(c) / 2.0,
        None => 0.1,
    }
}

/// Converts one adaptive-card row from the engine's native space (metres for `range`,
/// METRIC metres for `drop_linear`/`wind_linear`, metric m/s and J for `velocity`/`energy`)
/// into the run's display units. `drop_adj`/`wind_adj` are already expressed in the chosen
/// `--adjustment` printed unit by `adaptive_card` itself and must NOT be touched here --
/// only the fields `CardRow`'s own "display-ready, do not re-convert" convention has not
/// yet applied to need this. Needed because `range_table_row_line` (Task 9) and the PDF
/// dope card (Task 10) both expect display-ready values per that same convention, while
/// `adaptive_card` works entirely on `HoldCurve`'s native metric grid (Task 11).
fn adaptive_card_display_row(r: &CardRow, units: UnitSystem) -> CardRow {
    let linear_from_meters = |meters: f64| match units {
        UnitSystem::Imperial => meters / 0.0254,
        UnitSystem::Metric => meters * 1000.0,
    };
    CardRow {
        range: UnitConverter::distance_from_metric(r.range, units),
        drop_linear: r.drop_linear.map(linear_from_meters),
        drop_adj: r.drop_adj,
        come_up: r.come_up,
        wind_linear: r.wind_linear.map(linear_from_meters),
        wind_adj: r.wind_adj,
        velocity: r.velocity.map(|v| UnitConverter::velocity_from_metric(v, units)),
        energy: r.energy.map(|v| UnitConverter::energy_from_metric(v, units)),
        time: r.time,
        lead_adj: r.lead_adj,
        wind_columns: r.wind_columns.clone(),
    }
}

/// Formats an adaptive-card row's `range` for table/CSV: a bare integer when within floating-
/// point noise of one, one decimal place otherwise (review fix I-1, `4e69435`'s review).
///
/// `HoldCurve::SAMPLE_INTERVAL_M` is 0.9144 m, so under `--units metric` almost every
/// algorithm-chosen interior row is genuinely fractional (and a user's own `--anchor` can be
/// fractional in either unit system) -- `{:.0}` silently rounds it, which made the table and
/// CSV disagree with `-o json`'s exact value and with `-o pdf` (whose `format_range`,
/// `src/pdf_dope_card.rs`, already applies this identical rule). This is a **separate copy**
/// of that same rule, not a shared call: `pdf_dope_card::format_range` is private to a module
/// gated behind the `pdf` feature, while adaptive-card's table/CSV must render with `pdf`
/// disabled too. Keep the two in sync by hand if the rounding rule ever changes.
///
/// Deliberately NOT applied to `range_table_row_line` (Task 9): that function is golden-
/// pinned by `tests/card_golden_cli.rs` and `range-table`'s own display units are always
/// whole, so it is left untouched; adaptive-card gets its own row formatter,
/// `adaptive_card_row_line`, below.
fn format_adaptive_card_range(range: f64) -> String {
    let rounded = range.round();
    if (range - rounded).abs() < 0.05 {
        format!("{:.0}", rounded)
    } else {
        format!("{:.1}", range)
    }
}

/// Adaptive-card's own table row formatter (review fix I-1): byte-identical column layout to
/// `range_table_row_line` (same widths, same separators, same non-Range formats), but the
/// Range cell goes through [`format_adaptive_card_range`] instead of `{:>6.0}` -- formatted to
/// a string first, then right-padded to the same 6-wide field `range_table_row_line` uses, so
/// an integer range (the common case: both domain ends under imperial units, or any range that
/// happens to land on a whole display unit) renders byte-for-byte like before. A fractional
/// range -- ordinary under `--units metric`, or any explicit `--anchor` that doesn't land on a
/// whole unit -- now prints its one decimal place instead of a silently rounded integer, which
/// is what makes it agree with `-o json`/`-o pdf` at last.
///
/// `range_table_row_line` itself is UNTOUCHED (see its own doc comment): golden-pinning it
/// means the hard constraint "the 12 goldens must stay byte-identical" is satisfied by
/// construction, not by proof -- `range-table` never calls this function at all.
fn adaptive_card_row_line(r: &CardRow) -> String {
    format!(
        "│{:>6} │{:>8.1} │{:>8.3} │{:>8.1} │{:>8.2} │{:>8.0} │{:>8.0} │{:>6.2} │",
        format_adaptive_card_range(r.range),
        r.drop_linear.unwrap(),
        r.drop_adj.unwrap(),
        r.wind_linear.unwrap(),
        r.wind_adj.unwrap(),
        r.velocity.unwrap(),
        r.energy.unwrap(),
        r.time.unwrap()
    )
}

/// Maps a [`CardError`] into a CLI-facing message, naming the flag the user typed wherever
/// one exists (`--start`/`--end`/`--anchor`/`--elevation-budget`/`--windage-budget`/
/// `--max-rows`) -- the same "name the flag, not the struct field" convention
/// `require_angular_pair` established (MBA-1348 review fix). `InvalidTrackingCf` has no
/// adaptive-card flag of its own: this command sources the tracking CF only from
/// `--profile`, and `load_profile` already validates `elevation_cf`/`windage_cf` into the
/// identical `(0.5, 1.5)` band on load (MBA-1358), so in practice this arm cannot be
/// reached through this CLI surface today. It is still mapped -- `CardError` is not
/// `#[non_exhaustive]`, and a future direct `--elevation-cf`/`--windage-cf` override (or a
/// hand-edited profile loaded by a path that skips validation) must get a message, not a
/// panic -- so `CardError`'s own `Display` text is used verbatim for it.
fn adaptive_card_error_message(err: CardError, units: UnitSystem) -> String {
    let dist_unit = match units {
        UnitSystem::Imperial => "yd",
        UnitSystem::Metric => "m",
    };
    let disp = |m: f64| UnitConverter::distance_from_metric(m, units);
    match err {
        CardError::EmptyOrInvertedDomain { start_m, end_m } => format!(
            "--start {:.3} {dist_unit} and --end {:.3} {dist_unit} must describe a forward \
             interval with a positive start",
            disp(start_m),
            disp(end_m)
        ),
        CardError::AnchorOutsideDomain { anchor_m, start_m, end_m } => format!(
            "--anchor {:.3} {dist_unit} lies outside --start {:.3} {dist_unit} / --end \
             {:.3} {dist_unit}",
            disp(anchor_m),
            disp(start_m),
            disp(end_m)
        ),
        CardError::NonPositiveBudget { axis, value } => format!(
            "--{axis}-budget must be positive and finite (resolved to {value} in the chosen \
             --adjustment unit)"
        ),
        CardError::ZeroMaxRows => "--max-rows must be at least 1".to_string(),
        CardError::DomainOutsideCurve { requested_m, curve_max_m } => format!(
            "--end {:.3} {dist_unit} is past the solved trajectory's last reachable point at \
             {:.3} {dist_unit}",
            disp(requested_m),
            disp(curve_max_m)
        ),
        CardError::InvalidTrackingCf { .. } => err.to_string(),
    }
}

/// The footer block every `adaptive-card` output carries: budget met / rows (of the max) /
/// worst measured error and where / the verification grid it was measured on. Printed
/// directly under the table on stdout; written to stderr for csv/pdf so their primary
/// output channel (the CSV data rows; the PDF file) stays exactly that and nothing else.
/// `-o json` carries the identical facts as struct fields instead and gets no footer at all
/// -- see [`AdaptiveCardReportV1`] and the `-o json` arm below.
fn adaptive_card_footer(
    report: &AdaptiveCardReportV1,
    units: UnitSystem,
    unit_label: &str,
    max_rows: usize,
) -> String {
    use std::fmt::Write as _;
    let dist_unit = match units {
        UnitSystem::Imperial => "yd",
        UnitSystem::Metric => "m",
    };
    let mut out = String::new();
    let _ = writeln!(out);
    let _ = writeln!(out, "budget met: {}", if report.budget_met { "yes" } else { "no" });
    let capped = if report.rows_capped { " (row cap reached)" } else { "" };
    let _ = writeln!(out, "rows: {} of {max_rows} max{capped}", report.rows.len());
    let _ = writeln!(
        out,
        "worst error: elevation {:.4} {unit_label}, windage {:.4} {unit_label} @ {:.3} {dist_unit}",
        report.worst_elevation_error,
        report.worst_windage_error,
        UnitConverter::distance_from_metric(report.worst_error_range_m, units)
    );
    let _ = writeln!(
        out,
        "verification grid: {:.4} {dist_unit} step",
        UnitConverter::distance_from_metric(report.verification_grid_step_m, units)
    );
    out
}

/// `adaptive-card` dispatch (MBA-1351 Task 12): resolves the load and (optionally) the
/// optic from `--profile` via the same `InverseSolverLoadArgs`/`ProfileData::optic_profile`
/// pattern `dial-plan` uses, solves one `HoldCurve` out past `--end` (mirroring
/// `mark-to-range`'s own 2% search-headroom convention), then hands the resolved budgets
/// and optional click graduations to [`adaptive_card`]. Unlike `dial-plan`, a profile with
/// no optic data is not an error here -- quantization is optional for a range card (the
/// exact unrounded angle is a perfectly good answer), where `dial-plan`'s entire purpose
/// requires one.
#[allow(
    clippy::too_many_arguments,
    reason = "flat arguments mirror the stable adaptive-card CLI command shape"
)]
fn handle_adaptive_card(
    load_args: InverseSolverLoadArgs,
    zero_distance: Option<f64>,
    start: f64,
    end: f64,
    anchors: Vec<f64>,
    elevation_budget: Option<f64>,
    windage_budget: Option<f64>,
    max_rows: usize,
    adjustment: AdaptiveCardAdjustmentArg,
    output_file: Option<PathBuf>,
    units: UnitSystem,
    output: OutputFormat,
) -> Result<(), Box<dyn Error>> {
    let (load, profile_data) = load_args.resolve(zero_distance, units)?;

    // Optic is OPTIONAL here (unlike dial-plan): no --profile, or a --profile with no
    // turret/click data saved, both just mean "print exact, unquantized angles."
    let optic = match &profile_data {
        Some(p) => p.optic_profile().map_err(|e| format!("profile '{}': {e}", p.name))?,
        None => None,
    };
    // elevation_cf/windage_cf live on ProfileData independently of the twelve turret/optic
    // fields, so they resolve the same way regardless of whether `optic` above is Some or
    // None. load_profile already validates a stored value into the (0.5, 1.5) band
    // (MBA-1358), so this is never an out-of-band value in practice -- adaptive_card's own
    // CardError::InvalidTrackingCf check runs anyway, since this is also a public library
    // entry point other callers reach without the CLI's validation.
    let elevation_cf = profile_data.as_ref().and_then(|p| p.elevation_cf).unwrap_or(1.0);
    let windage_cf = profile_data.as_ref().and_then(|p| p.windage_cf).unwrap_or(1.0);

    let unit = adjustment.to_engine();
    let unit_label = adjustment.label();
    let unit_factor = unit.from_mil_factor();

    // Budgets parse via the same suffix-mandatory parse_angular_mil rule every other
    // angular CLI flag in this file uses -- as a clap value_parser on the field itself (see
    // the AdaptiveCard variant above), exactly like dial-plan's angular flags, so a missing
    // suffix is a clap usage error naming this flag ("invalid value '...' for
    // '--elevation-budget <VALUEUNIT>'") rather than an unnamed one. What's left here is
    // only the TRUE-mil -> --adjustment-unit conversion, applied identically to an explicit
    // value and the profile-derived default so the two paths cannot silently diverge.
    let elevation_budget_printed = match elevation_budget {
        Some(v) => v * unit_factor,
        None => {
            adaptive_card_default_budget_mil(optic.as_ref().map(|o| &o.elevation_click)) * unit_factor
        }
    };
    let windage_budget_printed = match windage_budget {
        Some(v) => v * unit_factor,
        None => {
            adaptive_card_default_budget_mil(optic.as_ref().map(|o| &o.windage_click)) * unit_factor
        }
    };

    let start_m = UnitConverter::distance_to_metric(start, units);
    let end_m = UnitConverter::distance_to_metric(end, units);
    let anchors_m: Vec<f64> =
        anchors.iter().map(|&a| UnitConverter::distance_to_metric(a, units)).collect();

    // Search a little past --end so a domain end landing exactly on the curve's last sample
    // still brackets -- the same 2% headroom `mark-to-range`/`bdc-match` solve with.
    let max_solve_range_m = if end_m.is_finite() && end_m > 0.0 { end_m * 1.02 } else { end_m };
    let curve = HoldCurve::solve(&load, max_solve_range_m)?;

    let click = optic.as_ref().map(|o| (&o.elevation_click, &o.windage_click));
    let req = AdaptiveRequest {
        domain_m: (start_m, end_m),
        anchors_m,
        budget: AdaptiveBudget { elevation: elevation_budget_printed, windage: windage_budget_printed },
        max_rows,
        click,
        elevation_cf,
        windage_cf,
        // No --zero-set on this command's interface (MBA-1360 zero sets are out of scope
        // for Task 12's brief); a card is always relative to the plain, unbiased zero.
        bias_mil: 0.0,
    };

    let report =
        adaptive_card(&curve, &req, unit).map_err(|e| adaptive_card_error_message(e, units))?;

    let (dist_unit, drop_unit, vel_unit, energy_unit) = match units {
        UnitSystem::Imperial => ("yd", "in", "fps", "ft-lb"),
        UnitSystem::Metric => ("m", "mm", "m/s", "J"),
    };
    let display_rows: Vec<CardRow> =
        report.rows.iter().map(|r| adaptive_card_display_row(r, units)).collect();

    match output {
        OutputFormat::Json => {
            // Verbatim: AdaptiveCardReportV1's own Serialize impl IS the wire format here,
            // unlike the four Task 9 surfaces' hand-built json! objects -- no footer, since
            // every fact the footer states is already a field on this struct.
            println!("{}", serde_json::to_string_pretty(&report)?);
        }
        OutputFormat::Csv => {
            let unit_lower = unit_label.to_lowercase();
            println!(
                "range_{dist_unit},drop_{drop_unit},drop_{unit_lower},wind_{drop_unit},wind_{unit_lower},velocity_{vel_unit},energy_{energy_unit},tof_s"
            );
            for r in &display_rows {
                println!(
                    "{},{:.1},{:.3},{:.1},{:.2},{:.0},{:.0},{:.2}",
                    format_adaptive_card_range(r.range),
                    r.drop_linear.unwrap(),
                    r.drop_adj.unwrap(),
                    r.wind_linear.unwrap(),
                    r.wind_adj.unwrap(),
                    r.velocity.unwrap(),
                    r.energy.unwrap(),
                    r.time.unwrap()
                );
            }
            eprint!("{}", adaptive_card_footer(&report, units, unit_label, max_rows));
        }
        OutputFormat::Table => {
            println!();
            println!(
                "Adaptive Range Card (zero: {:.0} {dist_unit}) -- method: {}",
                UnitConverter::distance_from_metric(load.zero_distance_m, units),
                report.method
            );
            println!(
                "┌───────┬─────────┬─────────┬─────────┬─────────┬─────────┬─────────┬───────┐"
            );
            println!(
                "│Range  │Drop     │Drop     │Wind     │Wind     │Vel      │Energy   │ToF    │"
            );
            println!(
                "│({:>2})   │({:>2})     │({:>3})    │({:>2})     │({:>3})    │({:>3})    │({:>4})   │(s)    │",
                dist_unit, drop_unit, unit_label, drop_unit, unit_label, vel_unit, energy_unit
            );
            println!(
                "├───────┼─────────┼─────────┼─────────┼─────────┼─────────┼─────────┼───────┤"
            );
            for r in &display_rows {
                println!("{}", adaptive_card_row_line(r));
            }
            println!(
                "└───────┴─────────┴─────────┴─────────┴─────────┴─────────┴─────────┴───────┘"
            );
            print!("{}", adaptive_card_footer(&report, units, unit_label, max_rows));
        }
        #[cfg(feature = "pdf")]
        OutputFormat::Pdf => {
            let output_path = output_file.as_ref().ok_or("PDF output requires --output-file")?;
            let range_unit = match units {
                UnitSystem::Imperial => RangeUnit::Yards,
                UnitSystem::Metric => RangeUnit::Meters,
            };
            // The dope-card PDF header is always imperial, matching `trajectory -o pdf`'s
            // own PdfMetadata convention -- HoldCurveLoad is already metric-normalized
            // regardless of --units, so this converts unconditionally rather than
            // branching on the run's own unit system.
            let velocity_fps = UnitConverter::velocity_from_metric(load.velocity_mps, UnitSystem::Imperial);
            let temperature_f =
                UnitConverter::temperature_from_metric(load.temperature_c, UnitSystem::Imperial);
            let pressure_inhg =
                UnitConverter::pressure_from_metric(load.pressure_hpa, UnitSystem::Imperial);
            let altitude_ft = UnitConverter::altitude_from_metric(load.altitude_m, UnitSystem::Imperial);
            let wind_speed_mph =
                UnitConverter::wind_from_metric(load.wind_speed_mps, UnitSystem::Imperial);
            let weight_gr = UnitConverter::mass_from_metric(load.mass_kg, UnitSystem::Imperial);
            let da_ft = calculate_density_altitude(altitude_ft, pressure_inhg, temperature_f);

            let rifle_name = profile_data
                .as_ref()
                .map(|p| p.name.clone())
                .unwrap_or_else(|| "Adaptive Card".to_string());
            let bullet = profile_data.as_ref().and_then(|p| p.bullet_name.clone()).unwrap_or_default();

            let pdf_config = DopeCardConfig {
                rifle_name,
                location: String::new(),
                density_altitude_ft: da_ft,
                pressure_inhg,
                pressure_hpa: load.pressure_hpa,
                temperature_f,
                altitude_ft,
                wind_speed_mph,
                target_speed_mph: 0.0,
                solver_mode: if cfg!(feature = "online") { "online".to_string() } else { "offline".to_string() },
                powder: String::new(),
                bullet,
                weight_gr,
                bc: load.bc,
                drag_model: load.drag_model.to_string(),
                velocity_fps,
                font_scale: 1.0,
                bold_data: false,
                elevation_unit_label: unit_label.to_string(),
                windage_unit_label: unit_label.to_string(),
            };

            let pdf_bytes = ballistics_engine::pdf_dope_card::generate_dope_card_pdf(
                &pdf_config,
                &display_rows,
                range_unit,
            )?;
            std::fs::write(output_path, &pdf_bytes)?;
            eprintln!("Adaptive range card PDF written to: {}", output_path.display());
            eprint!("{}", adaptive_card_footer(&report, units, unit_label, max_rows));
        }
        #[cfg(not(feature = "pdf"))]
        OutputFormat::Pdf => {
            return Err(
                "PDF output requires building with the 'pdf' feature (e.g. cargo build --features pdf)"
                    .into(),
            );
        }
    }

    Ok(())
}

/// Review fix I-1 (review of `4e69435`): `format_adaptive_card_range`/`adaptive_card_row_line`
/// pin the near-integer-then-one-decimal range rule and prove it does not disturb the seven
/// other columns.
#[cfg(test)]
mod adaptive_card_row_tests {
    use super::*;

    /// Mirrors `pdf_dope_card::format_range`'s own pinned examples (`src/pdf_dope_card.rs`)
    /// exactly -- this is a separate copy of that identical rule (see this fn's doc comment
    /// for why it can't be a shared call), so matching its already-reviewed fixtures keeps
    /// the two provably in sync rather than merely similar by construction.
    #[test]
    fn format_adaptive_card_range_matches_the_pdf_dope_cards_pinned_examples() {
        assert_eq!(format_adaptive_card_range(400.0), "400");
        assert_eq!(format_adaptive_card_range(417.3), "417.3");
        assert_eq!(format_adaptive_card_range(400.02), "400");
        assert_eq!(format_adaptive_card_range(399.98), "400");
        assert_eq!(format_adaptive_card_range(100.0 + 1e-9), "100");
        assert_eq!(format_adaptive_card_range(100.5), "100.5");
        assert_eq!(format_adaptive_card_range(400.08), "400.1");
    }

    /// I-1's exact reproduction: a real `--anchor`/interior-row value must print its one
    /// decimal, not a silently rounded integer that disagrees with `-o json`/`-o pdf`.
    #[test]
    fn format_adaptive_card_range_does_not_silently_round_a_real_anchor() {
        assert_eq!(format_adaptive_card_range(412.5), "412.5");
        assert_eq!(format_adaptive_card_range(307.2384), "307.2");
    }

    fn sentinel_row(range: f64) -> CardRow {
        CardRow {
            range,
            drop_linear: Some(222.1),
            drop_adj: Some(333.2),
            come_up: None,
            wind_linear: Some(555.4),
            wind_adj: Some(666.5),
            velocity: Some(777.6),
            energy: Some(888.7),
            time: Some(9.123),
            lead_adj: None,
            wind_columns: Vec::new(),
        }
    }

    /// Same anti-transposition technique as
    /// `card_row_sentinel_tests::range_table_row_line_places_each_sentinel_in_its_own_column`
    /// (Task 9): `expected` is a literal, independently hand-typed string, not produced by
    /// calling the function under test. Two cases -- an integer range (the common case,
    /// previously-correct and must stay so) and a fractional one (the I-1 fix) -- so fixing
    /// the Range column is proven not to disturb the seven columns it must leave alone.
    #[test]
    fn adaptive_card_row_line_places_each_sentinel_in_its_own_column() {
        let integer_row = sentinel_row(111.0);
        let line = adaptive_card_row_line(&integer_row);
        let expected =
            "│   111 │   222.1 │ 333.200 │   555.4 │  666.50 │     778 │     889 │  9.12 │";
        assert_eq!(line, expected);

        let fractional_row = sentinel_row(111.4);
        let line = adaptive_card_row_line(&fractional_row);
        let expected =
            "│ 111.4 │   222.1 │ 333.200 │   555.4 │  666.50 │     778 │     889 │  9.12 │";
        assert_eq!(line, expected);
    }
}
